programs.sol:
"""Approximate a negative formatting/separator signal.

Indentation and escaped newlines get the strongest negative values. Standalone
syntax and line endings get smaller ones; ordinary word pieces stay near zero.
Import declarations are a lexical exception. Constants are rounded training
means of these readable categories, not a table of tokenizer identities.
The state records the previous token and the current line's indentation.
"""
READS = ()
IMPORT_WORDS = frozenset(('import', 'from', 'package', 'using'))
LAYOUT_COMMANDS = frozenset(('left', 'right', 'label', 'begin', 'end'))


def spacing(s, previous, line_start, position):
    if '\r' in s:
        return -0.83
    if position == 0:
        return 0.39
    if line_start:
        if previous.endswith('\n\n'):
            return -0.77
        if '\n' in s:
            return -0.61
        if s.count(' ') <= 1 and '\t' in s:
            return -1.42
        if previous.startswith(' ') and previous.isspace():
            return -1.24
        if len(s) == 1:
            return -1.16
        if len(s) <= 4:
            return -1.73
        return -1.31 if len(s) <= 12 else -1.0
    if '\n' in s:
        if '\t' in s:
            return -1.02
        if s.count('\n') >= 2:
            return -0.11
        return -0.52 if previous[-1:].isdigit() else -0.17
    if previous.isspace():
        return -0.17
    if previous[-1:].isalpha():
        return -0.05 if len(s) == 1 else -0.22
    if previous.rstrip().endswith(('`', '+', '-')):
        return -0.77
    if previous.rstrip().endswith('='):
        return -0.59
    return -0.26 if previous[-1:].isdigit() else -0.37


def token_value(s, previous, line_start, indent, position, declaration):
    z = s.strip()
    if s.isspace():
        return spacing(s, previous, line_start, position)
    if s == 'n' and previous.endswith('\\'):
        return -1.12
    if z in ('\\n', '\\r', '\\t'):
        return -0.35
    if z.startswith('<|'):
        return 0.05
    if '\n' in s:
        if z.startswith(('.', '?', '!')) and ';' not in z and '{' not in z:
            return 0.01
        if ';' in z:
            return -0.73
        if '{' in z or '}' in z:
            return -0.6
        if z.startswith(':') and previous[-1:].isalpha():
            return 0.0
        return -0.27 if previous[-1:].isalpha() else -0.34
    letters = any(c.isalpha() for c in z)
    if letters or any(c.isdigit() for c in z):
        if position == 0:
            return 0.11
        if line_start and z.startswith('#'):
            return -1.16
        if line_start and z in IMPORT_WORDS:
            return -0.97
        if declaration:
            return -0.54
        if previous.endswith('\\') and z in LAYOUT_COMMANDS:
            return -0.42
        if line_start and '\t' in s:
            return -0.54
        if line_start and not letters and indent >= 2:
            return -0.26
        return -0.01
    if line_start and position > 0 and z[:1] in '=+-*/^_<>&|':
        return -0.81
    if z.startswith('\\'):
        return -0.33
    if z.startswith('$'):
        return -0.45
    if '=' in z:
        return -0.39 if len(z) <= 2 else 0.02
    if z.startswith(')'):
        if s.startswith(' '):
            return -0.44
        return -0.23 if previous[-1:].isdigit() else -0.14
    if z.startswith(('}', ']')):
        return -0.28
    if z.startswith(('(', '{', '[')):
        return -0.05 if s.startswith(' ') else -0.19
    if z.startswith(('"', "'")):
        if previous.endswith(','):
            return -0.68
        return -0.54 if line_start and position > 0 else -0.06
    if z.startswith('`'):
        return -0.06
    if z.startswith(('^', '_')):
        return -0.18
    if z.startswith(('•', '#')):
        return -0.3
    return -0.19 if z.startswith(';') else -0.02


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, start, indent, position, declaration = '', True, 0, 0, False
    else:
        _, previous, start, indent, position, declaration = carry
    s = prefix.token_strings[-1]
    value = token_value(s, previous, start, indent, position, declaration)
    declaration = start and s.strip() in IMPORT_WORDS
    if '\n' in s or '\r' in s:
        tail = s.replace('\r', '\n').rsplit('\n', 1)[-1]
        start = not tail.strip()
        indent = len(tail) if start else 0
    elif start and s.isspace():
        indent += len(s)
    else:
        start = False
    return (doc, s, start, indent, position + 1, declaration), value

"""Dotted numeric identifiers and network/cloud configuration vocabulary.

The large response is to the latter parts of dotted numbers (versions and
addresses), especially familiar IPv4 prefixes, and to compounds such as
load balancer, security group and network interface. Smaller responses cover
the associated configuration nouns. The shell separator &&, /bin, and the word "server"
receive negative values. Small rules also cover URL separators and single-letter
command options. The recent text is reset at document boundaries.
"""
import re

READS = ()

def noun_forms(words):
    import inflect
    engine = inflect.engine()
    return {form for word in words.split()
            for form in (word, engine.plural_noun(word))}


NETWORK_OBJECTS = noun_forms(
    'ip ipv4 ipv6 port protocol subnet gateway router pod namespace addr '
    'device module host vm'
)
RESOURCE_FIELDS = noun_forms(
    'rule group account instance volume secret spec template configuration '
    'selector attachment policy source'
)
TIMING_FIELDS = {'timeout', 'interval', 'threshold', 'seconds', 'retry'}
NETWORK_TOOLS = {'iptables', 'kubernetes', 'bgp', 'nat', 'tcp', 'udp', 'ssl'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent = ''
    else:
        recent = carry[1]
    token = prefix.token_strings[-1]
    before = recent
    recent = (recent + token)[-96:]
    value = 0.0

    # Only the visible part of a dotted number is used, never a later octet.
    if token in '0123456789.' and len(token) == 1:
        match = re.search(r'(?<![\d.])(\d+(?:\.\d*)*)$', recent)
        if match:
            groups = match[1].split('.')
            dots = len(groups) - 1
            if 2 <= dots <= 3 and all(len(g) <= 3 for g in groups[:-1]):
                # Distinctive local address prefixes; 10.* is ambiguous.
                private = (groups[0] == '127'
                           or groups[:2] in [['192', '168'], ['169', '254']]
                           or (groups[0] == '172' and groups[1].isdigit()
                               and 16 <= int(groups[1]) <= 31))
                first_digit = len(groups[-1]) == 1
                if len(groups[-1]) <= 1:
                    value = 1.15 if first_digit else 0.8
                    if dots == 3:
                        value *= 1.3
                    if private:
                        value = (4.0 if first_digit else 2.9)
                        if dots == 3:
                            value += 0.6
                    elif all(g == '0' for g in groups[:-1]):
                        value = 2.7 if first_digit else 2.0
                        if dots == 3:
                            value += 0.7
                else:
                    value = 0.8 if private and dots == 3 else 0.08

    word = token.strip(' \t\r\n._-/').lower()
    capitalized = any(c.isupper() for c in token)
    if word in NETWORK_OBJECTS or (capitalized and word in RESOURCE_FIELDS):
        value = 0.30
    if word in TIMING_FIELDS and capitalized:
        value = 0.55
    if word in NETWORK_TOOLS:
        value = 0.40

    # Recognize compounds even when the tokenizer splits them internally.
    if token and token[-1].isalpha():
        joined = re.sub(r'[ _-]+', '', recent.lower())
        if joined.endswith(('loadbalancer', 'loadbalancers')):
            value = 4.1
        elif joined.endswith(('loadbal', 'loadbalancing', 'loadbalance')):
            value = 2.2
        elif joined.endswith('volumeclaim'):
            value = 3.7
        elif joined.endswith('persistentvolume'):
            value = 1.8
        elif joined.endswith(('securitygroup', 'securitygroups',
                              'resourcegroup', 'resourcegroups')):
            value = 3.0
        elif joined.endswith(('targetgroup', 'targetgroups')):
            value = 2.0
        elif joined.endswith(('networkinterface', 'networkinterfaces')):
            value = 3.3
        elif joined.endswith('vpc'):
            value = 1.8
        elif (word == 'advertised' or
              (word == 'arn' and (capitalized or not before[-1:].isalpha()))):
            value = 0.9
        elif word in {'server', 'servers'}:
            value = -0.36

    if token.strip() == '&&':
        value = -0.45
    elif token == '/bin':
        value = -0.65
    elif token == '://':
        value = 0.30
    elif len(token) == 1 and token.isascii() and token.isalpha():
        if before.endswith(' -'):
            value = 0.65

    return (doc, recent), value

programs.haiku:
"""Networking-infrastructure and dotted-address detector (layer-1 MLP neuron 4483).

The neuron responds to two kinds of text.

1. Dotted numbers such as IP addresses (`192.168.0.1`, `127.0.0.1`) and version numbers
   (`1.0.2`). Its largest responses come at the third dot of an address and at the first
   digit of each part after the second dot. The second dot of a version number fires less,
   and later digits within a part barely fire.
2. Network-infrastructure vocabulary: load balancers and VLANs most of all; then subnets,
   TCP, gateways, replicas, and Cisco-style router configuration prompts (`)#`, `-if`);
   more weakly ports, NAT, interfaces, routers, switches, rules, policies, pods and clusters.

Shell operators (`&&`, `/bin`, `--`) and the word `server` push it slightly negative.
Everything else is near zero.
"""
READS = ()

NUMERIC = set("0123456789.")
STRONG = {"balancer": 2.0, "vlan": 2.0, ")#": 1.5, "-if": 1.5, "subnet": 1.0, "tcp": 1.0,
          "gateway": 0.8, "replica": 0.8}
WEAK = {"selector": 0.5, "interfaces": 0.5, "pods": 0.4, "protocol": 0.4, "cluster": 0.3,
        "router": 0.3, "pod": 0.3, "port": 0.3, "interface": 0.3, "switch": 0.3, "mask": 0.3,
        "nat": 0.3, "ip": 0.2, "rule": 0.2, "policy": 0.2, "dns": 0.4, "udp": 0.5}
SHELL = {"&&": -0.4, "/bin": -0.6, "--": -0.2, "server": -0.4}


def word_value(tok):
    word = tok.strip().lower()
    if tok.strip() in STRONG:
        return STRONG[tok.strip()]
    if word in WEAK:
        return WEAK[word]
    return SHELL.get(tok.strip(), 0.0)


def number_value(tok, run):
    """`run` is the dotted-number text so far, ending with `tok`."""
    before = run[: len(run) - len(tok)]
    dots = before.count(".")            # dots already seen in this number
    first_of_part = before.endswith(".")
    if tok == ".":
        return {1: 0.9, 2: 2.0}.get(dots, 1.0)
    if dots == 2:
        return 1.3 if first_of_part else 0.4
    if dots >= 3:
        return 1.5 if first_of_part else 0.8
    return 0.0


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    run = carry[0] if carry is not None and carry[1] == doc else ""
    numeric = bool(tok) and set(tok) <= NUMERIC
    run = run + tok if numeric else ""
    if numeric and run.count(".") >= 2:
        value = number_value(tok, run)
    else:
        value = word_value(tok)
    return (run, doc), value

programs.sol:
"""Estimate a short-chunk / word-continuation response.

A lone Han character following another lone Han character usually gets a
negative value. Common individual characters weaken that penalty; a frequent two-
character word strengthens it. Longer Han chunks get a small positive value.
Kana, Korean and Thai use simpler script/length rules. Han and Korean rules
notice leading whitespace. Byte fragments and document starts have separate rules.
These are approximate textual cues, not memorized token activations.
"""
import math
from functools import lru_cache
import regex
from opencc import OpenCC
from wordfreq import get_frequency_dict

READS = ()
SCRIPTS = ('Han', 'Hiragana', 'Katakana', 'Hangul', 'Thai')
FREQUENCIES = get_frequency_dict('zh')
SIMPLIFY = OpenCC('t2s')


@lru_cache(maxsize=32768)
def describe(raw):
    text = raw.decode('utf-8', 'replace').strip()
    for script in SCRIPTS:
        if text and regex.fullmatch(r'\p{Script=' + script + r'}+', text):
            return text, script
    return text, ''


@lru_cache(maxsize=16384)
def frequency(text):
    """Log corpus frequency per billion words; normalize traditional Han."""
    count = FREQUENCIES.get(SIMPLIFY.convert(text), 1e-9)
    return max(0.0, math.log10(count) + 9.0)


@lru_cache(maxsize=32768)
def han_continuation(previous, current):
    before, now = frequency(previous), frequency(current)
    together = frequency(previous + current)
    # Soften the penalty further for very frequent individual characters.
    value = (-1.04 + 0.060 * before + 0.054 * now - 0.072 * together
             + 0.18 * max(before - 6, 0) + 0.15 * max(now - 6, 0))
    return max(-1.4, min(0.15, value))


def step(carry, prefix, upstream):
    doc, raw = prefix.document_ids[-1], prefix.token_bytes[-1]
    initial = carry is None or carry[0] != doc
    previous_raw = b'' if initial else carry[1]
    previous, previous_script = describe(previous_raw)
    text, script = describe(raw)
    size, previous_size = len(text), len(previous)
    same_script = script == previous_script
    separated = bool(raw) and raw[:1].isspace()
    previous_fragment = bool(previous_raw) and 128 <= previous_raw[0] < 192
    value = -0.001

    if initial:
        if script == 'Han':
            value = 1.1 if size == 1 else -0.22 if size == 2 else 0.05
        else:
            value = 0.15 if separated else 0.25
    elif script == 'Han':
        if size > 1:
            value = 0.09 if size == 2 else 0.05
        elif separated:
            value = 0.0
        elif same_script and previous_size == 1:
            value = han_continuation(previous, text)
        elif previous_fragment:
            value = -0.57
        elif previous.isdigit():
            value = -0.41
        else:
            value = -0.03
    elif script == 'Hiragana':
        if size == 1:
            value = -0.4 if same_script and previous_size == 1 else -0.2
            if previous_size != 1 and not same_script:
                value = -0.02
        else:
            value = -0.02 if size == 2 and previous_size == 1 else 0.1
    elif script == 'Katakana':
        value = (-0.2 if same_script else 0.04) if size == 1 else 0.1
        if size == 2:
            value = -0.01 if same_script else 0.15
    elif script == 'Hangul':
        value = 0.02
        if size == 1 and not separated:
            if previous_fragment:
                value = -0.57
            elif same_script and previous_size == 1:
                value = -0.43
            elif previous.isdigit():
                value = -0.48
            else:
                value = -0.01
    elif script == 'Thai':
        value = 0.06 if size >= 3 else 0.02
        if same_script and size == 1:
            value = -0.14 if previous_size == 1 else -0.06
        elif same_script and size == 2 and previous_size == 1:
            value = -0.05

    # A token may finish a UTF-8 character begun in the preceding token.
    if not initial and raw and 128 <= raw[0] < 192:
        joined = (previous_raw + raw).decode('utf-8', 'ignore')
        completed = joined[len(previous_raw.decode('utf-8', 'ignore')):]
        _, completed_script = describe(completed.encode('utf-8'))
        value = -0.18 if completed_script == 'Han' else 0.0
        if completed_script == 'Hangul':
            value = 0.1
    return (doc, raw), value

"""A detector for brain-related spellings and short BR syllables.

Large responses go to brain, neuro- and cerebr- spellings; token splits
can amplify them. Short bra/bro fragments and b+r joins also respond,
while most complete BR words are weak. A small trace lasts one token.
Non-Latin letters are transliterated; documents reset the spelling buffer.
"""
import re
from functools import lru_cache
from anyascii import anyascii

READS = ()

@lru_cache(maxsize=65536)
def spelling(text):
    # Japanese bu and Korean beu spell the B of a borrowed BR cluster.
    text = text.replace('ブ', 'b').replace('브', 'b')
    if not text.isascii():
        # Do not turn emoji names (e.g. the brain emoji) into words.
        text = ''.join(anyascii(c) if c.isalpha() else c for c in text)
    return text.lower()


def response(before, token):
    s, old = spelling(token), spelling(before)
    compact = bool(s and s[0].isalpha())
    word = s.strip()
    if word in ('brain', 'brains'):
        return 7.08 + 3.25 * compact
    if word == 'neuro':
        return 3.3  # neuro
    if old.endswith('ne') and s == 'uro':
        return 3.41  # neuro join
    if word.startswith('cerebral'):
        return 3.92  # cerebral
    mode, stem = '', ''
    if 'br' in s:
        mode, stem = 'inside', s[s.rfind('br'):]
    elif compact:
        if old.endswith('b') and s.startswith('r'):
            mode, stem = 'bridge', 'b' + s
        else:
            m = re.search(r'br[aeiouy]?$', old)
            if m:
                mode, stem = 'continued', m[0] + s
    if not stem:
        return 0.0  # background
    if compact and old.endswith(('cere', 'sere', 'cereb', 'sereb',
                                 'cerebr', 'serebr')):
        whole = old + s
        if 'cerebro' in whole or 'serebro' in whole:
            return 13.84  # cerebro join
        if 'cerebra' in whole or 'serebra' in whole:
            return 7.63  # cerebra join
        return 3.48  # cerebr join
    if stem.startswith('brain') and mode != 'inside':
        exact = stem in ('brain', 'brains')
        return 14.76 if exact else 9.7
    if mode in ('bridge', 'continued') and stem.startswith('braid'):
        return 3.89  # joined braid
    if mode == 'bridge':
        if s in ('ra', 'ro', 'rya'):
            return 4.61  # joined open syllable
        if s == 'rea':
            return 5.98  # joined rea
        if stem.startswith(('bra', 'bro', 'brya')):
            return 1.36  # joined bra bro
        if stem.startswith('bre'):
            return 0.1  # joined bre
        return 0.89  # joined other br
    if mode == 'continued':
        if stem in ('breast', 'breasts'):
            return 3.64  # joined breast
        if s in ('a', 'o', 'ya'):
            return 1.5  # continued vowel
        if stem.startswith(('bra', 'brya')):
            return 0.86  # continued bra
        if stem.startswith('bri'):
            return -0.16  # continued bri
        return 0.26  # continued other br
    if word in ('bra', 'bro'):
        return 3.24 + 2.36 * (compact and word == 'bro')
    letters = re.match(r'[a-z]+', stem)[0]
    if letters == 'br':
        return 0.21  # bare br
    if letters.startswith('breast') and letters != 'breastfeeding':
        return 2.02  # breast
    if letters in ('brake', 'brakes'):
        return 1.69  # brake
    if letters == 'brow':
        return 2.12  # brow
    if letters.startswith('brook'):
        return 0.98  # brook
    if letters.startswith('braid'):
        return 3.0  # braid
    return 0.12  # other br



def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, trace, raw = '', 0., b''
    else:
        _, before, trace, raw = carry
    # Recover characters whose UTF-8 bytes straddle two tokens.
    combined = raw + prefix.token_bytes[-1]
    decoded = combined.decode('utf-8', errors='ignore')
    token = decoded[len(raw.decode('utf-8', errors='ignore')):]
    signal = response(before, token)
    value = -0.0014 + signal + 0.01 * trace
    return (doc, (before + token)[-24:], signal, combined[-16:]), value

programs.haiku:
"""Brain-word detector for layers.1.mlp.down_proj:4485.

A reader's-eye view: the program keeps the last few characters of the text
(lowercased) and asks whether the word being spelled out is "brain" (or
"cerebro/cerebral", "neuro", or the Chinese 脑 / 腦 for brain). It predicts a
strong activation on the token that completes "brain", a weaker one on the
start fragments "bra", "bro", "brow", "breast" and a weak one when a token ending
in "b" is followed by one starting with "r". Everything else predicts 0.
"""

READS = ()

BR_FRAGMENTS = {"bra", "bro", "brow", "breast", "breasts", "brook", "brai"}
COMPUTER = ("电脑", "電腦")


def step(carry, prefix, upstream):
    tail = carry or ""
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        tail = ""
    cur = prefix.token_strings[-1].strip().lower()
    text = tail + cur
    if "brainstorm" in cur:
        value = 0.0
    elif cur.startswith("brain"):
        value = 7.5
    elif "brain" in text and "brain" not in tail:
        value = 11.5
    elif "cerebro" in text and "cerebro" not in tail:
        value = 15.0
    elif "cerebr" in cur or tail.endswith("cerebr"):
        value = 5.0
    elif cur == "neuro":
        value = 3.3
    elif cur.endswith(("脑", "腦")) and cur not in COMPUTER:
        value = 8.3
    elif cur in BR_FRAGMENTS:
        value = 3.3
    elif tail.endswith("b") and cur.startswith(("ra", "ro")):
        value = 2.3
    elif tail.endswith("b") and cur.startswith("r"):
        value = 1.1
    else:
        value = 0.0
    return text[-12:], value

programs.sol:
"""A sparse mixture of phrase completions and character/encoding cues.

The strongest English responses finish compounds such as 'climate change'.
'Talk' is negative mainly as a noun or a word fragment, while 'talking' is
positive, especially after a present-tense form of 'be'.  Greek consonants
inside words and a few Thai vowel combinations form separate character cues.
An isolated UTF-8 lead byte C2 is positive in mojibake-like contexts.
Initial Title: headers and repeated separators are small additional cues.
Everything else is approximated by zero.  Only a short text tail is retained.
"""
import re
import regex

READS = ()

# Established compounds: (modifier, final word) -> response.
COMPOUNDS = {
    ('climate', 'change'): 5.15,
    ('behavior', 'change'): 3.2,
    ('behaviour', 'change'): 3.2,
    ('global', 'warming'): 2.3,
    ('world', 'war'): 1.05,
    ('problem', 'statement'): 0.45,
    ('lecture', 'notes'): 3.0,
    ('gun', 'violence'): 0.7,
    ('domestic', 'violence'): 1.5,
    ('homework', 'help'): 0.75,
    ('grand', 'theft'): 2.8,
    ('math', 'forum'): 2.3,
}
NOUN_MARKERS = set('a an the this that my your his her its our their '
                   'some no self pep tech peace'.split())
GREEK = regex.compile(r'\p{Script=Greek}')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, position = b'', 0
    else:
        _, tail, position = carry
    b = prefix.token_bytes[-1]
    s = prefix.token_strings[-1]
    text = tail.decode('utf-8', errors='ignore')
    last = text[-1:]
    word_match = re.search(r'\w+$', text)
    previous = word_match.group().lower() if word_match else ''
    word = s.lstrip(' -').lower()
    value = COMPOUNDS.get((previous, word), 0.0)
    # These two heading/name completions depend on capitalization.
    if word in {'war', 'help'} and s.lstrip(' -').islower():
        value = 0.0

    if word == 'talking':
        value = 0.6
        if previous in {'re', 'am', 'm', 'i'}:
            value = 3.0
        elif previous in {'are', 'were', 'not', 'the', 'a', 's'}:
            value = 1.5
    elif word in {'talk', 'talks'}:
        if not s.startswith(' '):
            value = -3.2 if s.startswith('T') else -1.9
        elif previous in NOUN_MARKERS:
            value = -4.2 if previous == 'this' else -1.8
            if previous == 'tech':
                value = -3.5
        elif s[1:2].isupper():
            value = -1.8
        else:
            value = 0.0
    elif s.lower() == 'alk':
        value = -0.4
