"""Layer 1, MLP down projection, component 4486: a stray-byte and word-pair detector.

What it responds to, in plain terms:

* Stray UTF-8 bytes in garbled text. The strongest case is the lone byte 0xC2 (token
  id 126), the first half of a two-byte character such as © or ° or a non-breaking
  space. When it arrives alone it shows as a replacement character. It fires when the
  text before it is non-ASCII, and most strongly (about 6) right after a Thai letter.
  The byte that follows a stray byte, shown as a replacement character after a Thai
  letter, also fires moderately (about 3).
* The word "change" completing "climate change" (about 5). "warming" after "global"
  and "War" after "World" fire weakly.
* "talking" fires weakly positive. "talk" and "talks" fire weakly negative, and a
  capitalised "Talk" (as in wiki "Talk" pages) fires negative.
* The Greek letter beta (β) inside a Greek word is strongly negative (about -3.4).

Everywhere else it predicts 0. Values are typical activations, not fitted to eval.
"""

READS = ()

LEAD_BYTE_C2 = 126  # token id of the raw byte 0xC2 (decodes alone to U+FFFD)
REPLACEMENT = "�"


def has_thai(text):
    return any("฀" <= ch <= "๿" for ch in text)


def has_greek(text):
    return any("Ͱ" <= ch <= "Ͽ" for ch in text)


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before_raw = prefix.token_strings[-2] if same_doc else ""
    before = before_raw.strip().lower()

    if prefix.token_ids[-1] == LEAD_BYTE_C2:
        if has_thai(before_raw):
            return carry, 5.9
        if before_raw and not before_raw.isascii():
            return carry, 3.0
        return carry, 0.0
    if raw == REPLACEMENT and has_thai(before_raw):
        return carry, 3.0
    if raw == "β" and has_greek(before_raw):
        return carry, -3.4
    if word == "change" and before == "climate":
        return carry, 5.0
    if word == "warming" and before == "global":
        return carry, 2.5
    if word == "war" and before == "world":
        return carry, 0.9
    if word == "talking":
        return carry, 1.0
    if word in ("talk", "talks", "alk"):
        return carry, -0.5
    if raw == "Talk":
        return carry, -3.4
    return carry, 0.0

