"""Approximate a collection of code-punctuation responses, not ordinary prose.

The largest rules recognize diff --git, Ruby symbol prefixes, and spaced
:: in functional-language types/lists. Smaller rules distinguish qualified
names, tests, proof syntax, variable sigils, PHP tags, and dotted leaders.
These are rounded training estimates. A recent-text buffer supplies simple
language cues and resets between documents; unrecognized tokens get zero.
"""
import re

READS = ()


def ruby_context(text):
    """Conservative Ruby cues: declarations, accessors, and colonless methods."""
    if re.search(r'\bmy\s+[@$]|#!/\S*perl\b', text):
        return False
    return bool(re.search(
        r'(?:^|\n)[ \t]*@\w+\s*(?:=(?!=)|\|\|=)|'
        r'\{\s*\|\w+|\bdo\s+\||'
        r'\.rb\b|\bStruct\.new|(?<![.:])\battr(?:_\w+)?\b|'
        r'\b(?:belongs_to|has_many|has_one)\b|'
        r'\bclass [A-Z]\w*\s+<\s+|'
        r'(?:^|\n)\s*(?:module \w+|'
        r'def [\w.]+[!?]?(?:\([^\n]*\))?)[ \t]*\n', text))


def predict(token, before):
    if token == 'git':
        return 7.0 if before.endswith('diff --') else -0.2
    if token == 'php' and before.endswith('<?'):
        return -2.13 if before == '<?' else -0.35
    if token == '··':
        return 0.56  # a pair of middle dots in dotted leaders
    if token == ' RUN':
        return 0.64 if before.endswith('===') else 0.18
    if token not in ('::', ' ::', '(:', ' :', '@', ' @', '@@', ' @@',
                     ' by', ' |', ' ->', ' =>', '[:', '{:', ' {:'):
        return 0.0

    text = before.replace('\\n', '\n')
    line = text.rsplit('\n', 1)[-1]
    ruby = ruby_context(text)
    if token == '(:':
        return -7.0 if ruby or text.endswith(('.new', '.save')) else -1.0
    if token in ('[:', '{:', ' {:'):
        return -5.0 if ruby else 0.0
    if token == ' :':
        if ruby:
            declaration = re.search(
                r'\b(?:attr(?:_\w+)?|(?:has|belongs)_\w+|'
                r'validates?\w*|property|action)\s*$', line)
            if declaration:
                return -10.0  # attribute, association, or validation declarations
            if line.lstrip().startswith('#') or re.search(r'\s\?\s+\S', line):
                return -0.5  # prose comments or a ternary-operator colon
            return -7.0
        if line.rstrip().endswith(',') and '(:' in text:
            return -7.0
        if re.search(r'<[A-Za-z]\w*$', line):
            return -3.2  # a shorthand bound attribute, as in <a :href
        if line.rstrip().endswith('='):
            return -1.3  # a named bind parameter or symbol value
        if not line.strip() and '.. autosummary::' in text:
            return -2.0  # an indented documentation directive option
        if (not line.strip() and ':param ' in text) or line.lstrip().startswith(':param '):
            return -0.5
        if '-- goal' in text:
            return -0.35
        return -0.10
    if token in ('@@', ' @@'):
        if not line.strip():
            return -1.32
        return -0.9 if line.endswith('=') else -0.15
    if token in ('@', ' @'):
        if ruby:
            if not line.strip():
                return -6.0 if token.startswith(' ') else -4.5
            return -1.2
        if re.search(r'\b(?:SET|IF)\s*$', line):
            return -1.5
        if line.rstrip().endswith('='):
            return -0.62
        if line.rstrip().endswith('*'):
            return 0.11  # Javadoc tags
        if re.search(r'\bpublic (?:class|void|static)|\bnew [A-Z]', text):
            return 0.1
        if not line.strip() and re.search(r'\b(?:def |import )', text):
            return -0.4
        return 0.0
    if token in (' ->', ' =>'):
        return 1.1 if ' :: ' in line else 0.0
    if token == ' |':
        return -1.0 if text.endswith(' do') else 0.0
    if token == ' by':
        formal = '\\<' in text and re.search(r'\b(?:lemma|simp|qed|have)\b', text)
        return 2.2 if formal or text.rstrip().endswith(':=') else 0.0

    # Double colons: test names, type/list syntax, or scope resolution.
    word = re.search(r"[\w.']+\s*$", line)
    word = word.group().strip() if word else ''
    if line.endswith('.py'):
        return 0.98
    if '.py::' in line:
        return 0.10
    if text.endswith('['):
        return 4.0  # omitted slice bounds, or [:: in an IPv6 address
    if re.search(r'\[[0-9a-fA-F]+$', line):
        return 2.0
    if word == 'std':
        return -0.23
    rust = bool(re.search(
        r'\.rs\b|\bfn |\blet mut |\bimpl\b|\buse [a-z_]', text))
    cpp = '#include' in text or 'namespace ' in text
    if token == ' ::' and not (rust or cpp):
        if word and word[0].islower():
            return 3.8
        if word[:1].isdigit():
            return 2.5
        if text.rstrip().endswith(')'):
            return 3.0
        return 0.0
    if cpp or word[:1].isupper():
        return -0.08
    return 0.76 if rust else 0.4


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    last_doc, before = carry if carry is not None else (None, '')
    if doc != last_doc:
        before = ''
    token = prefix.token_strings[-1]
    value = predict(token, before)
    return (doc, (before + token)[-1500:]), value

