"""A negative detector of short ca/ka spelling fragments, especially cat/kat.

The spelling may be inside the newest token or split after a c/k in the
previous token. Transliteration extends the same rule to other scripts.
Most longer spelling chunks receive weaker estimates than short fragments.
Other positions are zero: small positive and token-specific effects are omitted.
These are spelling rules, not a detector of the animal or the shell command.
"""
import re
from functools import lru_cache
from anyascii import anyascii

READS = ()

@lru_cache(maxsize=16384)
def romanize(text):
    # Alif represents a here; AnyAscii otherwise omits this Arabic vowel.
    text = text.translate(str.maketrans('اأآإ', 'aaaa'))
    return anyascii(text).lower().strip(" \n\r\t_.$/\\-`'\"([]{}):")


def response(previous, token):
    p, t = romanize(previous), romanize(token)
    adjacent = not token[:1].isspace()
    split = adjacent and p.endswith(('c', 'k')) and t.startswith('a')
    syllabic_ka = (adjacent and p.endswith(('ca', 'ka'))
                   and t[:1].isalpha())
    matches = list(re.finditer('[ck]a', t))
    # A newly completed ka syllable, possibly followed by a consonant.
    if split or syllabic_ka:
        tail = t[1:] if split else t
        if tail in ('t', 'ts'):
            return -4.5 if p.endswith('c') else -3.2
        if tail.startswith('t'):
            if len(p) > 4:
                return -0.5 if p.endswith(('ic', 'ik')) else -1.2
            return -3.0 if len(t) <= 4 else -1.6
        if not tail:
            return -2.5 if token.strip().isupper() else -0.4
        if tail.startswith('h') and len(t) <= 2:
            return -3.0
        if tail.startswith(('b', 'd', 'z', 'h', 'j', 'ch', 'v', 'w', 'c', 'g')):
            return -1.4 if len(t) <= 3 else -0.7
        return -0.25
    if not matches:
        return 0.0
    # Inside a token, emphasize the short cat/kat family, not every ca word.
    m = matches[-1]
    tail = t[m.end():]
    if m.start() > 1:
        return -0.04
    if tail in ('t', 'ts'):
        return -2.9 if token[:1].isspace() else -3.5
    if tail.startswith('t'):
        if len(tail) > 1 and tail[1] in 'aeiouh':
            return -1.5 if len(t) <= 7 else -0.5
        return -0.1
    if len(tail) <= 2 and tail.startswith(('b', 'd', 'z', 'j', 'ch')):
        return -2.0 if token.isascii() else -2.6
    if not tail:
        return -0.5 if t.endswith('ca') else -0.2
    return -0.1 if len(t) <= 4 else -0.03


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, token), response(previous, token)

"""Detect 'on' and 'upon', chiefly as separate prepositions.

Ordinary 'on' is positive.  Complements such as 'based on', 'focus on',
'effect on', and common verb particles are weaker; 'and so on' is negative.
Capitalization and a few other languages' prepositions have their own levels.
At a document start, punctuation, quotation marks, English articles and the
chat-start marker have separate baselines.  Initial runs of middle dots are
strongly positive.
Other tokens are assigned zero; this omits many small lexical responses.
