PREPOSITIONS = {
    'upon': 0.83,
    'onto': 0.18,
    'sur': 0.66,
    'på': 1.03,
    'op': 0.35,
    'auf': 0.20,
    'pe': 0.15,
    'na': 0.19,
    'على': 0.59,
    'на': -0.22,
