    r'\b(?:bas(?:e|ed|ing)|depend\w*|focus\w*|'
    r'rel(?:y|ies|ied|ying|iance)|effects?|impacts?|emphasis|influence)'
    r'(?:\s+(?:heavily|mainly|only|more|primarily|entirely|solely))*\s*$'
