READS = ()


def split_prefix(previous, current, character, cut=1):
    """Match the next byte of this sample character's shared UTF-8 prefix."""
    encoded = character.encode('utf-8')
    return (previous == b' ' + encoded[:cut]
            and current == encoded[cut:cut + 1])


