"""Key-value separators in object literals (JSON, JS/TS objects, PHP/Ruby hashes).

layers.1.mlp.down_proj:4496 fires on the colon that separates a key from its value
when the key sits inside braces `{...}`: the closing quote-colon of a JSON key
(`"name":`), a quoted key (`'name':`), an escaped JSON key (`\\":`), and a bare
`key:` in a JS object literal. The strongest case is `":` inside a JSON object.
Colons in prose, times, ratios, `key :` with a space, and colons inside
parentheses stay near zero. `=>` (PHP/Ruby hash arrows) fires weakly. A few
list connectives (" and", " etc", " also", " the", ...) and commas get a small
constant, because they carry a small, diffuse positive activation. Everything else is 0.

The program tracks which bracket is innermost, reset at each document start.
"""

READS = ()

KEY_CLOSE = {'":', "':", '\\":'}          # quoted key followed by its colon
LIST_WORDS = {" and", " etc", " also", " other", " are", " that", " which", " such", " or", " the"}


def step(carry, prefix, upstream):
    stack = carry or ""                     # open brackets, innermost last
    if len(prefix) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        stack = ""                          # the model resets at a new document
    tok = prefix.token_strings[-1]
    in_braces = stack[-1:] == "{"

    if tok in KEY_CLOSE:
        value = 1.15 if in_braces else 0.6
    elif tok == ":":
        value = 0.85 if in_braces else 0.02
    elif tok.strip() == "=>":
        value = 0.4
    elif tok in LIST_WORDS:
        value = 0.05
    elif tok == ",":
        value = 0.03
    else:
        value = 0.0

    for ch in tok:
        if ch in "{[(":
            stack += ch
        elif ch in "}])" and stack:
            stack = stack[:-1]
    return stack, value

