    return (doc, position + 1, raw), value

"""Predict a sparse mixture of character and short-phrase responses.

Boost isolated sight (视/視) and food (食) characters, attenuating them
when the preceding-character pair is a frequent Chinese word. Handle split
UTF-8 completions separately. Other rules cover class declarations, help-page
wording, code comments, document-opening markers and repeated middle dots.
This is a partial approximation: unrecognized cases receive zero.
"""
from wordfreq import get_frequency_dict
from math import log10
from opencc import OpenCC
import re

READS = ()
SIMPLIFY = OpenCC('t2s')
CHINESE_FREQUENCIES = get_frequency_dict('zh')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, previous, position = b'', '', 0
    else:
        _, history, previous, position = carry
    raw = prefix.token_bytes[-1]
    token = prefix.token_strings[-1]
    before = history.decode('utf8', 'replace')
    text = (history + raw).decode('utf8', 'replace')
    state = (doc, (history + raw)[-256:], token, position + 1)
    word, prev = token.strip(), previous.strip().lower()
    value = 0.0

    # Read completed characters even when UTF-8 spans several tokens.
    split = bool(raw and 0x80 <= raw[0] < 0xc0)
    char = text[-1:] if split else token
    if char in ('视', '視', '食'):
        if split:
            value = 6.0 if char in ('视', '視') else 2.0
        else:
            pair = SIMPLIFY.convert(text[-2:])
            frequency = CHINESE_FREQUENCIES.get(pair, 0.0)
            commonness = max(0, 9 + log10(frequency)) if frequency else 0
            value = max(0.05, (2.9 - 0.5 * commonness)
                        if char != '食' else (1.5 - 0.2 * commonness))

    elif token == ' class':
        if prev == 'public':
            value = -1.3 if previous == 'public' else -0.65
        elif prev in ('export', 'final'):
            value = -0.5
    elif token == ' result' and before.lower().endswith("here's the"):
        value = -0.45
    elif word.lower() == 'knowledge' and before.lower().endswith('test your'):
        value = 1.4
    elif word.lower() == 'question':
        value = 1.5 if before.lower().endswith('rate this') else 0.0
        if before.lower().endswith('submit your'):
            value = 1.5
    elif word.lower() == 'questions':
        if before.lower().endswith('browse other') or prev == 'new':
            value = 1.4
        elif prev in ('your', 'these', 'other', 'following'):
            value = 0.55
        elif prev in ('the', 'my', 'few', 'more', 'all'):
            value = 0.25
    elif word.lower() in (
        'solution', 'solutions', 'answer', 'answers', 'equations'
    ):
        if before.lower().endswith('search our') and word == 'solutions':
            value = 2.5
        elif before.lower().endswith('write your'):
            value = 1.0
        elif prev in ('your', 'my', 'this', 'these', 'our'):
            value = 0.4
        elif prev == 'other' and word.lower() == 'answers':
            value = 1.0
        elif prev == 'of' and word.lower() in ('solutions', 'equations'):
            value = 0.65
        elif prev == 'all' and word == 'Solutions':
            value = 1.35
        elif prev == 'an' and word == 'answer':
            value = 0.35
        elif prev == 'correct' and word == 'answer':
            value = 0.15
    elif word.lower() in ('news', 'posts') and prev == 'latest':
        value = 0.7
    elif token == '#define' and re.search(r'#ifndef[^\n]*\r?\n$', before):
        value = 1.4 if '_' in before.splitlines()[-1] else 0.4
    elif token == ' Templates' and before.endswith('Tools |'):
        value = 0.94
    elif token == '-doc' and previous == '-user':
        value = 1.45
    elif token == 'Views' and before.endswith('\n') and 'Replies' in before:
        value = 0.85
    elif token == ' directed' and before.endswith('should be'):
        value = 1.8
    elif token == '··' and (position == 0 or previous == '··'):
        value = 2.23
    elif token == ':' and position == 1 and previous == 'Title':
        value = 2.46
    elif position == 0:
        if token == ' .':
            value = 2.2
        elif token == '**':
            value = 1.7
        elif token == '//\n':
            value = 3.04
        elif token == 'import':
            value = -0.43
        elif token == 'using':
            value = -0.81
        elif token == 'class':
            value = -1.25
    return state, value

