"""layers.1.mlp.down_proj:4505 -- a sparse, mostly-silent feature with a few token triggers.

Plain-language summary of what this program predicts:
- Strongest: the Chinese characters 視 / 视 ("sight, regard, view": 視覺, 重視, 視如己出) give about +2.2.
- Moderate: 食 ("food, eat": 食品, 食水, 食安) gives about +0.8.
- Java/C#-style class declarations: the word "class" right after "public" (or "export") gives about -1.0.
- "import" gives a small negative value, about -0.15.
- Document starts: a first token that is a digit, comma, "and", newline or "#" gives +0.25;
  a first token that is "the", "a", "of", "is", "(" or ":" gives -0.15.
- Everything else predicts 0.

Values are calibrated to the mean activation each trigger produced on ~7,000 training rows.
Most of the component's variance is spread over thousands of ordinary tokens with tiny
effects (|activation| < 0.2) that no short rule captures, so this program explains only a
few percent of the variance. A per-token lookup table would explain more (about 0.3 on
held-out training rows), but it would be a table of arbitrary token ids.
"""
READS = ()
SIGHT = {"視", "视"}
FOOD = {"食"}
PUBLIC_CLASS = ("public", "export")
FUNCTION_WORDS = {"the", "a", "of", "is", "(", ":"}
NUMBER_LIKE = {",", "and", "\n", "#"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    start = len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    v = 0.0
    if tok.strip() == "class" and prev.strip() in PUBLIC_CLASS:
        v = -1.0
    elif tok in SIGHT:
        v = 2.2
    elif tok in FOOD:
        v = 0.8
    elif tok.strip() == "import":
        v = -0.15
    elif start:
        w = tok.strip().lower()
        if tok.isdigit() or tok in NUMBER_LIKE or w == "and":
            v = 0.25
        elif w in FUNCTION_WORDS:
            v = -0.15
    return carry, float(v)

programs.sol:
"""A spelling-sensitive tail/detail/retail signal, usually near zero.

Tail and retail are strong, while detail and related spellings are weaker.
Completing these spellings across a token boundary can be especially strong:
`t` + `ailed`, or `DETA` + `ILED`.  German Teil and Latin-script til are
weaker neighbors.  Chinese dictionary equivalents supply a similar signal.
Tut/tent-like fragments receive negative predictions.
This is an approximation, not a general detector of everything about tails.
"""
import re
import unicodedata
from functools import lru_cache
import cedict
import regex

READS = ()


@lru_cache(maxsize=32768)
def normal(s):
    return ''.join(c for c in unicodedata.normalize('NFD', s.lower())
                   if not unicodedata.combining(c))


@lru_cache(maxsize=8192)
def chinese(s):
    if not regex.fullmatch(r'\p{Script=Han}+', s):
        return 0.0
    glosses = cedict.glosses(s)
    if 'tail' in glosses:
        return 5.2
    if any('to retail' in g for g in glosses):
        return 6.8 if len(s) > 1 else 1.2
    if any(re.match(r'(in )?detail(s|ed)?($|[;,])', g) for g in glosses):
        return 1.2
    return 0.0


def response(s, previous):
    w = normal(s.strip()).lstrip('._/-')
    if w.startswith('detail'):
        if w.endswith('details'):
            return 0.95
        if w == 'detail' and s.strip().startswith('D'):
            return 4.2
        return 1.8
    if w.startswith('retail'):
        if w.startswith('retailers'):
            return 5.4
        if w.startswith('retailer'):
            return 3.0
        return 8.1 if s.startswith(' ') else 10.3
    if w.startswith('tail'):
        if w.startswith('tailor'):
            return 1.6
        if w.startswith('taille'):
            return 1.0
        return 5.0 if s.startswith(' ') else 7.0
    if w.startswith('entail'):
        return 4.8
    joined = previous + normal(s) if s and s[0].isalpha() else w
    if (s and previous and s[0].isalpha() and 'tail' in joined
            and 'tail' not in previous and 'tail' not in normal(s)):
        return 3.8 if w.startswith(('ille', 'ailand')) else 8.1
    if 'teil' in w:
        return 1.2 if s.strip().startswith('T') else 2.6
    if 'teil' in joined and 'teil' not in previous:
        return 4.0
    if 'theil' in joined and 'theil' not in previous:
        return 2.1
    if (previous.endswith('t') and w in ('ile', 'iles', 'iling')
            and s[0].isalpha()):
        return 2.6
    if previous.endswith('detal') and w.startswith('h'):
        return 5.2
    if 'detal' in w:
        return 1.9
    if w in ('tai', 'til', 'tile', 'itle'):
        return 0.8
    if w == 'tut':
        return -2.5
    if w == 'tent':
        return -1.0
    if joined.endswith('tut'):
        return -1.5
    if joined.endswith('tenter'):
        return -4.3
    return chinese(s.strip())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    value = response(s, previous)
    m = re.search(r'[^\W\d_]+$', normal(s))
    word = m.group() if m else ''
    if word and len(word) == len(s):
        word = previous + word
    return (doc, word[-60:]), value

"""Sparse spelling rules for MY and related MI-like fragments.

Ordinary space-prefixed 'my' is weakly negative; capitalized/bare forms,
short -amy/-emy/-omy fragments, army and academy are stronger. Several
cross-token m + i/y spellings and non-Latin counterparts also get negative
values. Czech m + e-caron gets a positive value instead. Other tokens get
zero. Case, spacing and document starts affect the MY level; finer context
variation is deliberately not modeled. Only the previous token is carried.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    before = previous.lower()
    value = 0.0

    # Token-internal spellings, with a weaker level for the possessive.
    if lower.strip('._/(-') == 'my':
        if token == ' my':
            value = -0.7
        elif token == ' My':
            value = -1.8
        elif word == 'My':
            value = -2.0
        elif word == 'MY':
            value = -4.3
        else:
            value = -3.2
        if not previous:
            value = -3.2 if token == ' my' else -4.0
        elif previous == '<|endoftext|>':
            value = -7.0 if word == 'My' else -4.0
    elif lower in {'amy', 'emy', 'omy'}:
        value = -6.0 if lower == 'omy' else -4.7
    elif lower in {'army', 'academy'}:
        if lower == 'army':
            value = -3.1 if word[0].isupper() else -2.4
        else:
            value = -3.9
    elif lower == 'mi':
        value = -0.65
    elif word == 'ミ':
        value = -2.3
    elif word in {'米', '小米'}:
        value = -1.1

    # Adjacent pieces of one word, rather than a new space-prefixed word.
    if token and not token[0].isspace():
        if before.endswith('m'):
            if (token[0].lower() == 'y' and len(token) <= 3
                    and (len(token) == 1 or token[1].lower() not in 'aeiou')):
                value = -4.2 if len(token) == 1 else -6.0
            elif lower == 'ie':
                value = -3.8
            elif lower in {'ee', 'ies'}:
                value = -3.0
            elif lower in {'i', 'io', 'ij'}:
                value = -1.6
            elif token == 'ě':
                value = 2.4
        elif re.search(r'm[eié]$', before) and token[0].lower() == 'y':
            value = -3.2 if lower == 'y' else -1.5
        elif before.endswith('м'):
            if lower in {'и', 'ии', 'ы'}:
                value = -1.1
            elif lower == 'ыш':
                value = -5.0
        elif before.endswith('μ'):
            if token[0].lower() in 'ιίῖ':
                value = -2.8
            elif token[0].lower() in 'υύ':
                value = -7.0
        elif before.endswith('my') and len(token) <= 2 and token.isalpha():
            value = -4.0 if lower in {'el', 'os'} else -2.3
        elif before.endswith('م') and lower in {'ي', 'ى', 'ی'}:
            value = -1.5
        elif previous.endswith(('マ', 'メ')) and token == 'イ':
            value = -1.5
    return (doc, token), value

