"""layers.1.mlp.down_proj:4511, a component that fires on the word "of" when it follows a noun
naming a kind, system, method or arrangement ("a system of", "a mode of", "a method of",
"a team of", "a piece of", "a place of birth"). The "of" after such a noun is strongly positive;
other "of" are near zero. It also fires on the word "mixture" (and its pieces "mix"+"tures")
and on the Chinese noun-forming characters 子, 儿 and 兒.

Predicts the activation from the current token and the token before it only.
"""

READS = ()

# How strongly "X of" responds, by the noun X before "of" (rough means on training text).
KIND_NOUNS = {
    "system": 6.0, "mode": 4.0, "work": 2.4, "method": 2.3, "style": 2.1,
    "team": 1.8, "place": 1.8, "course": 1.6, "manner": 1.2, "mix": 1.2,
    "mixture": 1.1, "piece": 1.1, "body": 1.0, "species": 1.0, "basis": 0.9,
    "way": 0.8, "form": 0.6,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if token == " of":
        return None, KIND_NOUNS.get(previous, 0.0)
    if token.strip() in ("mixture", "ixture", "tures"):
        return None, 3.0
    if token.strip() in ("子", "儿", "兒"):
        return None, 1.5
    return None, 0.0

