"""Grammatical categories used to describe short function-word transitions."""
READS = ()

# Quantity words and selectors that can introduce 'of the ...'.
INDEFINITE_QUANTITY = {'some', 'many', 'much', 'few', 'several'}
UNIVERSAL = {'all', 'both', 'every'}
SELECTOR = {'one', 'each', 'either', 'neither', 'any', 'none'}
NUMBER = {'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine',
          'ten', 'eleven', 'twelve', 'hundred', 'thousand', 'million'}
PROPORTION = {'most', 'more', 'less', 'half', 'majority', 'minority',
              'rest', 'remainder', 'lot', 'lots', 'plenty'}
POSSESSIVES = {'my', 'your', 'his', 'her', 'its', 'our', 'their'}
DEMONSTRATIVES = {'this', 'that', 'these', 'those'}
COLLECTION = {'set', 'list', 'array', 'sequence', 'collection', 'series',
              'matrix', 'system', 'chain'}
SMALL_AMOUNT = {'hint', 'touch', 'bit', 'piece', 'glimpse', 'taste', 'trace'}
DUPLICATE = {'copy', 'copies', 'replica', 'replicas', 'duplicate', 'duplicates'}


def quantity(w):
    if w == 'some':
        return 'some'
    if w in INDEFINITE_QUANTITY:
        return 'indefinite'
    if w in UNIVERSAL:
        return 'universal'
    if w in SELECTOR:
        return w
    if w in NUMBER or w.isdigit():
        return 'number'
    if w in PROPORTION:
        return 'proportion'
    if w in {'percent', 'percentage', '%'}:
        return 'percentage'
    return ''


def category(s, prev, before):
    """A small decision tree on the current and two preceding token words."""
    w, p, q = s.strip().lower(), prev.strip().lower(), before.strip().lower()
    # Require an entire word token; a mid-word fragment is not an article.
    if not s.startswith(' '):
        return 'other'
    if w == 'the':
        if p == 'of':
            return 'the/of/' + (quantity(q) or 'ordinary')
        if p in UNIVERSAL:
            return 'the/universal'
        if p in {'among', 'amongst'}:
            return 'the/among'
        if (p in {"'s", '’s', 'is', 'are'} and q == 'here'):
            return 'the/presentation'
        if p in {'during', 'throughout', 'within'}:
            return 'the/duration_or_interior'
        if p == 'to' and q in {'due', 'owing'}:
            return 'the/due_to'
        if p in {'to', 'on', 'and', 'as', 'from'}:
            return 'the/' + p
        if p in {'is', 'are', 'was', 'were'}:
            return 'the/copula'
        return 'the/ordinary'
    if w == 'of':
        if quantity(p):
            return 'of/' + quantity(p)
        if p in COLLECTION:
            return 'of/collection'
        if p in SMALL_AMOUNT:
            return 'of/small_amount'
        if p in DUPLICATE:
            return 'of/duplicate'
        if p in {'example', 'examples', 'illustration', 'illustrations'}:
            return 'of/example'
        if p in {'lack', 'absence', 'deprivation'}:
            return 'of/absence'
        if p in {'end', 'beginning', 'start', 'completion'}:
            return 'of/boundary'
        return 'of/ordinary'
    if w in POSSESSIVES | DEMONSTRATIVES:
        if p == 'of' and quantity(q):
            return 'determiner/partitive'
        if p in UNIVERSAL:
            return 'determiner/universal'
        return 'determiner/ordinary'
    if w in {'a', 'an'}:
        if p in {"'s", '’s', 'is', 'are'} and q in {'here', 'there'}:
            return w + '/presentation'
        if p in {'is', 'are'}:
            return w + '/copula'
        if p == 'just':
            return w + '/just'
        return w + '/ordinary'
    if w == 'though' and p == 'even':
        return 'though/even'
    if w == 'as' and p == 'just':
        return 'as/just'
    return 'other'


