"""A spelling heuristic for short e-bearing continuations of Latin words.

Predict negative values for vowel/sonorant/e endings, especially after
short capitalized word fragments. The o endings also depend on how much
of the word the previous token supplied. Long non-capitalized stems can give
positive i-ending values. Amine, amide and azole endings get a separate
positive rule. English word frequency distinguishes rare fragments from
recognizable words. This does not infer pronunciation or chemical meaning.

State is only the trailing ASCII-letter run (up to 50 letters) and the
previous token's stripped length; both reset at document boundaries.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=8192)
def frequency(word):
    return zipf_frequency(word, 'en')


def ending_value(token, stem, previous_length):
    n = len(stem)
    capitalized = stem[:1].isupper()
    lower = stem.lower()
    if re.fullmatch(r'o[lnrm]es?', token):
        if previous_length <= 2:
            if n <= 1:
                return -0.24 if frequency(stem + token) < 4 else 0.10
            return -0.68 if n <= 6 else 0.02
        if capitalized:
            return -2.84 if n <= 4 else -0.77
        vowels = re.findall('[aeiou]', lower)
        return -2.53 if vowels and vowels[-1] == 'u' else -0.80
    if re.fullmatch(r'i[lnrm]es?', token):
        if capitalized:
            if n <= 2:
                return -0.77 if frequency(stem + token) < 1 else -0.06
            return -0.60 if frequency(stem) < 3 else -1.44
        if n <= 6:
            return -0.05 if n <= 2 else -0.36
        return 0.63 if lower.endswith('l') else 0.09
    if token in {'amine', 'amide', 'azole'}:
        if n <= 3:
            return 0.13
        return 1.69 if frequency(stem + token) < 1 else 1.15
    return -0.037


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        stem, previous_length = '', 0
    else:
        _, stem, previous_length = carry
    token = prefix.token_strings[-1]
    value = -0.003
    if (stem and re.fullmatch('[a-z]{1,6}', token)
            and token.endswith(('e', 'es'))):
        value = ending_value(token, stem, previous_length)
    match = re.search('[A-Za-z]+$', token)
    if match:
        stem = stem + token if match.start() == 0 else match.group()
        stem = stem[-50:]
    else:
        stem = ''
    return (doc, stem, len(token.strip())), value

