"""Layer 1, MLP down-projection, component 4515: a word-piece "spelling" feature.

In plain terms: the component reads the current token only through its text.
  * Strongly negative on a few short word-ending pieces that finish a longer
    word split into several tokens, e.g. "phot|ore|ceptor", "Oste|one|crosis",
    "Car|ole", "Par|ole".
  * Mildly negative on other common word-ending pieces such as -ine, -ile,
    -ice, -ise, -ace, -ule (as in "Mart|ine|au", "Constant|ine").
  * Positive on pieces of chemical names: -amine, -amide, -iline, -azole,
    -idine, -ylene (as in "ethylenediam|ine", "polyacrylam|ide").
  * Zero on every other token.
The sign of the real activation is context-dependent, so this is a coarse,
token-class average, not a full model of it.
"""

READS = ()

STRONG_NEG = {"one", "ore", "ole", "ones", "cone", "cake", "eline"}
WEAK_NEG = {"ine", "ile", "ice", "ise", "ace", "ule", "ode", "ame", "ake",
            "ose", "ores", "ules", "ines", "ille", "core", "ere", "ale"}
CHEM_POS = {"amine", "amide", "iline", "azole", "idine", "ylene"}
WEAK_POS = {"xe", "php", "agne"}


def step(carry, prefix, upstream):
    piece = prefix.token_strings[-1]
    if piece in STRONG_NEG:
        value = -1.0
    elif piece in WEAK_NEG:
        value = -0.35
    elif piece in CHEM_POS:
        value = 0.7
    elif piece in WEAK_POS:
        value = 0.25
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Mostly a detector for k-v / k-w clusters split between tokens.

It gives a large negative response at the second part of such a cluster,
except in familiar English compounds and the spelling 'ck'. There are
weaker responses to g/q/h plus v/w and to short kw/kv spellings. A few
cross-script versions and a short continuation of the cluster are included.
Training spellings such as Mosk-va and K-wa motivate these rules. This
is an activation estimate, not a pronunciation model. Repeated middle dots
have a separate positive response. Other positions are predicted as zero;
weaker scattered responses and partial-byte effects are not reproduced.
"""
from functools import lru_cache
import regex
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
LETTERS = regex.compile(r'[\p{Latin}\p{Cyrillic}\p{Greek}]')


@lru_cache(maxsize=20000)
def spelling(text):
    return anyascii(text).lower()


@lru_cache(maxsize=10000)
def familiar(word):
    return len(word) >= 3 and zipf_frequency(word, 'en') > 3.5


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    older, old = ('', '') if carry is None or carry[0] != doc else carry[1:]
    text = prefix.token_strings[-1]
    p, s = spelling(old), spelling(text)
    value = 0.0
    if (p and s and LETTERS.fullmatch(old[-1])
            and LETTERS.fullmatch(text[0])):
        last, first = p[-1], s[0]
        if last == 'k' and first in 'vw':
            value = -6.5
            if p.endswith('ck') or (familiar(p.strip()) and familiar(s)):
                value = -0.1
            elif text[0].isupper() and len(text) > 2 and text[1:].islower():
                value = 0.0  # CamelCase, rather than a spelling cluster
            elif old == 'K':
                value = -4.5
            elif old.strip() == 'k' and text.isupper() and len(text) > 1:
                value = -1.0
        elif last in 'gqh' and first in 'vw':
            value = -2.5 if last == 'q' else -0.5
            if old[-1] == 'г':
                value = -5.0
            elif familiar(p.strip()) or text[0].isupper():
                value = 0.0
        if p.endswith(('kw', 'kv')) and first in 'aeiou':
            value = -2.0 if p.strip() in ('kw', 'kv') else -0.5
        if (spelling(older).endswith('k') and p in ('v', 'w')
                and first in 'aeiou'):
            value = -4.5 if len(text) == 1 else -2.0
        if spelling(older).strip() == 'k' and old == 'в' and text == 'і':
            value = -6.0
    if old.endswith(('ク', 'グ')) and text in ('ア', 'イ', 'エ', 'ワ'):
        value = -5.5 if old.endswith('ク') else -2.5
    if old.endswith(('خ', 'ق')) and text.startswith('وا'):
        value = -1.5
    if old.endswith('ก') and text.startswith('ว'):
        value = -5.0
    # Kilo-watts, kilo-volts and Python's keyword-arguments are exceptions.
    if old.endswith('k') and text in ('W', 'Wh', 'V', 'VA'):
        value = -0.4
    if old.strip().lower() == 'k' and text.lower() in ('wh', 'ws'):
        value = -0.8
    if p.endswith('k') and text == 'wargs':
        value = 0.0
    short = text.strip()
    if short.lower() in ('kw', 'kv') and short not in ('kW', 'kV'):
        value = -2.0
    elif short == 'qv':
        value = -2.0
    elif short in ('gw', 'qw'):
        value = -0.8
    if old and text and set(old + text) == {'·'}:
        value = 1.3
    return (doc, old, text), value

"""Detect dense one-character items in a repeated delimiter pattern.

Examples are digit lists, initials, variables, music chords and letter codes.
The second item gives a weak response; two matching delimiters give a much
stronger one. Longer numbers contribute less. Group boundaries, decimal
points and escape sequences are not list delimiters. Wide padding weakens
the response; the state resets at document boundaries.
"""
READS = ()
CONNECTORS = {'and', 'or', 'to', 'through', 'by'}
QUOTES = str.maketrans('', '', '\"\'`“”‘’')


def separator(text):
    text = text.translate(QUOTES)
    compact = ''.join(text.split())
    if not compact:
        return 'newline' if '\n' in text else 'space' if text else ''
    if compact in {',', '.', '-', '–', '—', '/', '|', '+', '*',
                   '×', '&', '->', '→'}:
        return compact
    return ''


def signals(words, gap, char):
    """Weak pair evidence and strong repeated-separator evidence."""
    numeric = char.isdigit()
    signed = '-' in gap and (',' in gap or gap.startswith(' '))
    if numeric and ('.' in gap or signed):
        return 0.0, 0.0
    sep = separator(gap)
    if words and words[-1][0].lower() in CONNECTORS:
        sep = words[-1][0].lower()
        words = words[:-1]
    if not sep or not words:
        return 0.0, 0.0

    def weight(word):
        if numeric:
            if word.isdigit() and len(word) <= 4:
                return 1.0 / len(word)**2
            return 0.0
        return float(len(word) == 1 and word.isascii() and word.isalpha())

    first, before_first = words[-1]
    weak = weight(first) * (2.0 if sep in CONNECTORS else 1.0)
    strong = 0.0
    if separator(before_first) == sep:
        strong = weight(first)
        if len(words) >= 2:
            second, before_second = words[-2]
            strong *= weight(second)
            # Do not turn pieces of a dotted abbreviation into spaced words.
            if (not numeric and sep in {'space', 'newline'}
                    and separator(before_second) not in {'space', 'newline', ''}
                    and '\n' not in before_second):
                strong = 0.0
            if len(words) >= 3 and separator(before_second) == sep:
                strong *= 1.2
        # Padded table columns are weaker evidence than compact sequences.
        width = max(len(gap), len(before_first), 1)
        strong *= min(1.0, (4.0 / width)**2)
    return weak, strong


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, [], '', '')
    _, words, word, gap = carry
    token = prefix.token_strings[-1]
    start = next((i for i, c in enumerate(token) if c.isalnum()), len(token))
    leading = token[:start]
    continuation = bool(not leading and word)
    if leading and word:
        words.append((word, gap))
        word, gap = '', ''
    gap += leading
    chars = ''.join(c for c in token if c.isalnum())
    value = 0.0
    if len(chars) == 1 and chars.isascii() and not continuation:
        weak, strong = signals(words, gap, chars)
        if chars.isdigit():
            value = 0.25 * weak + 2.27 * strong
        else:
            value = 0.18 * weak + 1.55 * strong
    for c in token[start:]:
        if c.isalnum():
            word += c
        else:
            if word:
                words.append((word, gap))
                word, gap = '', ''
            gap += c
    return (doc, words[-8:], word, gap), value

programs.haiku:
"""Runs of standalone symbols: the layer-1 MLP neuron 4517 (the down_proj component
layers.1.mlp.down_proj:4517 reads only this neuron) is mostly silent, and fires when a single
letter or digit continues a list of single symbols:

- a capital letter in a run of symbols: cube-move strings ("R' B' U' R B"), initials and
  lettered lists ("A, B, C, ..."); strongest when the letter also steps the alphabet (B after A);
- a lowercase letter that steps the alphabet within a run ("a, b, c");
- a digit right after a comma in a number list ("1, 2, 3", "{2, 4, 6, 8"), when it follows another digit.

A "run" is the count of symbols in a row, where spaces, commas, quotes and brackets between
symbols do not break it. Anything else predicts 0."""

READS = ()

KEEP_RUN = " ,' ()[]{}"  # tokens made only of these characters do not break a run


def _core(s):
    return s.strip(KEEP_RUN)


def step(carry, prefix, upstream):
    # carry: (run length, last symbol, whether a comma came after the last symbol), None at a row start
    run, last, comma = carry if carry else (0, None, False)
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        run, last, comma = 0, None, False
    s = prefix.token_strings[-1]
    c = _core(s)
    if c == "":  # only separators: the run goes on, and remembers a comma
        return (run, last, "," in s or (comma and s.strip("  ") == "")), 0.0
    if not (len(c) == 1 and c.isascii() and c.isalnum()):
        return (0, None, False), 0.0  # any other token ends the run
    # does this symbol step the alphabet (or count up) from the previous one?
    succ = False
    if last is not None and c.isalpha() == last.isalpha():
        if c.isalpha():
            succ = ord(c) == ord(last) + 1 and c.isupper() == last.isupper()
        else:
            succ = int(c) == int(last) + 1
    run = run + 1 if last is not None else 1
    value = 0.0
    if c.isupper():
        value = {3: 0.14, 4: 0.14}.get(run, 0.6 if run >= 5 else 0.0)
        if succ and run >= 3:
            value += 2.4
    elif c.islower():
        if succ:
            value = 0.2 if run == 2 else 1.5
        elif run >= 3:
            value = 0.14
    elif comma and run >= 2:
        value = 0.4  # a number after a comma in a list
    return (run, c, False), value

programs.sol:
"""Title-case 'The' within a continuing phrase gives a negative response.

Sentence boundaries largely remove it; prepositions, naming/listing verbs and
conjunctions strengthen it. A mathematical "proof of" gets a smaller value. Local
capitalization, word frequency and verb status refine the estimate. Separate
rules cover unindented C# imports and repeated middle-dot separators. All other
tokens are assigned zero. Only a short text tail is carried between tokens.
"""
import re
from functools import lru_cache
import wordfreq
import wordnet

READS = ()

PREPOSITIONS = set('''of in to for with on at from by about as into like
through after over between out against during without before under around
among per via than toward upon within off until up down near using including
versus'''.split())


@lru_cache(maxsize=4096)
def word_properties(word):
    return (wordfreq.zipf_frequency(word, 'en'),
            'verb' in wordnet.parts_of_speech(word))


def article_value(text):
    last = text.rstrip()[-1:] or ' '
    sentence_tail = re.split(r'[.!?\n]', text)[-1]
    capitals = len(re.findall(r'\b[A-Z][a-z]', text[-100:]))
    if last in '.!?':
        return 0.11
    if text.endswith('\n'):
        return -0.04
    word = re.search(r'([A-Za-z]+)[^A-Za-z]*$', text)
    previous = word.group(1).lower() if word else ''
    if last.isalpha() or last in '"\'“‘':
        if re.search(r'(?i)\bproof\s+of\s*$', text):
            return -1.0
        if previous in PREPOSITIONS:
            return -3.9
        if previous in {'and', 'or', 'nor'}:
            return -4.2
        if previous in {'called', 'named', 'titled', 'entitled',
                        'include', 'includes', 'included'}:
            return -3.7
        if previous in {'is', 'are', 'was', 'were', 'be', 'been'}:
            return -2.8
    if last == ',':
        return -2.5
    if len(sentence_tail) <= 8:
        return -0.75 if capitals >= 3 else -0.22
    frequency, verb = word_properties(previous)
    if frequency > 5.6:
        return -1.55
    if last in ':;':
        return -0.15
    if capitals >= 3:
        return -1.2
    if verb:
        return -0.9
    return -0.42


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    text = '' if start else carry[1]
    token = prefix.token_strings[-1]
    value = 0.0
    if token.strip() == 'The':
        value = (-0.46 if token.startswith(' ') else -0.136) if start \
                else article_value(text)
    elif token == 'using':
        if start:
            value = -3.19
        elif re.search(r'\busing\s+[\w.]+;\s*$', text):
            value = -11.2
    elif token == ' System' and re.search(r'(?:^|\n)using$', text):
        value = -4.1
    elif len(token) >= 2 and set(token) == {'·'}:
        value = -1.72
    return (doc, (text + token)[-200:]), float(value)

"""Blood vocabulary and its spelling lookalikes.

The main response is negative on blood words, especially the character 血.
Completing blood/blut/sangre/sangue from separate pieces is stronger than
reading a whole blood token. Weaker rules cover bleed and bl- spellings.
Only the unfinished word is carried; document boundaries clear it.
"""
import re
from wordfreq import zipf_frequency

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    s = token.lower()
    joined = (before + s if s[:1].isalpha() else s).strip()
    value = 0.0

    if '血' in s:
        value = -10.0 if s.strip() == '血' else -1.6
    elif 'bloody' in s:
        value = -4.4
    elif 'blood' in s:
        value = -7.6 if 'Blood' in token else -6.5
    elif 'blood' in joined and 'blood' not in before:
        value = -10.0 if 'bloody' in joined else -15.5
    elif joined.startswith('blut') and not before.startswith('blut'):
        value = -15.5
    elif joined.startswith('warmblüt') and not before.startswith('warmblüt'):
        value = -8.0
    elif any(joined.startswith(w) and not before.startswith(w)
             for w in ('sangre', 'sangue')):
        value = -10.0
    elif s.strip() == 'sang':
        # French blood versus English past-tense "sing".
        if zipf_frequency(before, 'fr') > zipf_frequency(before, 'en') + 0.5:
            value = -6.5
    elif s.strip() in ('huyết', 'máu', 'кровь', 'крови'):
        value = -4.0
    elif 'bleed' in s:
        value = -3.2
    elif (joined.startswith('bleed') and not before.startswith('bleed')
          or before == 'b' and s.startswith('led')):
        value = -5.9
    elif before.endswith('bl') and s.startswith(('um', 'au', 'ü')):
        # German flower/blue spellings: Blumen, blau, blühen.
        value = -3.0
    elif s.strip() in ('bl', 'ble', 'blo', 'blue', 'blues'):
        value = -0.4
    elif (before.endswith('bl') or before in ('ble', 'blo')) and s[:1].isalpha():
        value = -0.4

    match = re.search(r'[^\W\d_]+$', before + token)
    word = match.group().lower()[-32:] if match else ''
    return (doc, word), value

"""Local spelling pulses, dominated by topological rather than ordinary top.

Training examples give a large negative value on top + ological, smaller
negatives on topology and topography, and positives on top-ranking phrases.
The rules approximate that distinction and two related mathematical word
families.  They also recognize Chinese 拓扑, with a smaller pulse on 拓 alone.
Only two previous tokens are kept; document boundaries reset them.  Weaker
responses to other spellings are left at zero, not modeled semantically.
