    if token.strip() == '拓':
        value = -3.7
    if '拓扑' in token or ('拓' in previous and '扑' in token):
        value = -10.0
    elif re.search(r'(?:^|[^a-z])topologic', token):
        value = -10.3
    elif re.search(r'(?:^|[^a-z])topolog', token):
        value = -4.1
    elif re.search(r'(?:^|[^a-z])topo', token):
        value = -2.3
    elif top:
        if token.startswith('ologic'):
            value = -10.3
        elif token.startswith('olog'):
            value = -4.3
        elif token.startswith('ographic'):
            value = -2.6
        elif token.startswith('ograph'):
            value = -1.5
        elif token == 'o':
            value = -6.2
        elif token.startswith(('pling', 'most', 'per')):
            value = 2.5
        elif token == '-':
            value = 2.4
        elif token.startswith('-'):
            value = 0.7
        elif token.strip().isdigit():
            value = 3.0
        elif token.startswith(' ') and token.strip():
            value = 0.35
        elif token and token[0].isalpha():
            value = -0.6
    elif p == 'home' and token.startswith('omorph'):
        value = -4.6
    elif p == 'hom' and token.startswith('ologic'):
        value = -2.5
    elif (p in ('-', '') and
          re.search(r'(?:^|[^a-z])top$', earlier.strip()) and
