    return (doc, token, previous), value

"""A lexical approximation to a degree/change-of-state signal.

Negative responses emphasize "pretty", "quite", "a bit", "a little",
and predicative "so". The previous two tokens help distinguish these
from conjunctions, literal kinds, and computer bits. Onset verbs,
"start to", and Chinese degree expressions also receive negative values.
Recognizable shell/regex symbols and a few locative/discourse phrases
receive positive values. Everything else defaults to zero.

This is a short-context rule approximation, not a sentence parser.
State resets when the document changes.
"""
import re

READS = ()

# Words which introduce a description of a state rather than a new clause.
STATE = set("""am is are was were be been being 'm 's 're ’m ’s ’re
feel feels felt feeling look looks looked looking seem seems seemed
growing grow grew
get gets got getting become becomes became becoming sound sounds
stay stays stayed remain remains remained turned turns turn""".split())
ONSET = set("""start starts started starting begin begins began beginning
begun commence commenced commencing""".split())

# Degree adverbs, grouped by their empirical response rather than spelling.
DEGREE = [
    (-1.15, set("totally somewhat incredibly utterly".split())),
    (-0.8, set("absolutely fairly".split())),
    (-0.15, set("completely entirely fully".split())),
    (-0.50, set("very too extremely slightly almost nearly".split())),
    (-0.30, set("really rather particularly especially highly".split())),
]
# Chinese degree expressions: small amount, emphasis, and ordinary degree.
CHINESE = [
    (-5.0, {"有点", "有點"}),
    (-2.2, {"有些", "挺", "特别", "特別", "格外", "超级", "超級"}),
    (-1.3, {"很", "非常", "比较", "比較", "这么", "這麼", "那么", "那麼"}),
    (-0.8, {"太", "真", "十分", "完全", "相当", "相當", "极为", "極為", "好", "超"}),
    (-1.5, {"巨", "真的很", "很是", "真是", "真的超"}),
