            return -1.4
        if state:
            return -3.0
        if previous in {'it', 'me', 'you', 'they', 'them', 'us', 'its'}:
            return -1.9
        if previous in {
            'in', 'with', 'has', 'have', 'had', 'take', 'takes',
            'put', 'into', 'of', 'for', 'thanks', 'just', 'why',
        }:
            return -1.5
        if previous.isalpha() and previous not in {
            'and', 'or', 'but', 'if', 'then', 'do', 'did', 'doing',
            'done', 'think', 'thought', 'believe', 'say', 'said', 'the',
