        literal_kind = before_previous in {
            'some', 'any', 'a', 'the', 'this', 'that', 'what', 'which',
        }
        return -0.1 if literal_kind else -2.3
    if word in {'kind', 'sort'} and (state or previous in {'it', 'i', 'you'}):
        return -1.8
    if word == 'kinda':
        return -2.5
    if word == 'how':
        return -0.65 if previous in {
            'know', 'knows', 'knew', 'see', 'show', 'shows', 'wonder',
            'learn', 'understand', 'about', 'realize', 'imagine',
        } else (-0.3 if token.strip() == 'how' else 0.0)
    if word in {'getting', 'started'}:
        return -1.2
    if word in {
        'get', 'gets', 'got', 'become', 'becomes', 'became', 'becoming',
    }:
        return -0.5
    if word in {'began', 'begun', 'felt', 'feels', 'feeling', 'grew'}:
        return -0.7
    if word in {
        'feel', 'look', 'looks', 'looked', 'sound', 'sounds', 'seem', 'seems',
    }:
        return -0.35
    if word in {
        'start', 'starts', 'starting', 'begin', 'begins', 'beginning',
    }:
        return -0.25
    if word in {'huge', 'massive', 'immense'}:
        return -0.5
    if word in {'lot', 'lots', 'plenty'}:
        return -0.6
    if word == 'right':
        if previous in {'the', 'a', 'your', 'my'}:
            return 0.0
