        if word == '$' and previous.endswith(('\\', '"', '@')):
            return 0.9
        if word == '*' and previous.endswith('\\'):
            return 0.6
        if word == '^' and previous.endswith('^'):
            return 1.2
        if '.*' in word or word == ':*':
            return 1.1
        if word in {'<!', '#!'}:
            return 1.8
        if '${' in word or '>&' in word or '\\$' in word:
            return 0.6
        if word == '$$':
            return 0.4 if token.startswith(' ') else 0.0
        if token.startswith(' {') and not token.endswith('\n'):
            return 0.17
        if word in {'{@', '@{', '(^', '^^'}:
            return 0.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous = before_previous = ''
    else:
        _, previous, before_previous = carry
    token = prefix.token_strings[-1]
    value = response(token, previous, before_previous)
    return (doc, token.strip().lower(), previous), float(value)

programs.haiku:
"""Degree and change words that open a predicate, in the layer-1 MLP down-projection unit.

It goes negative on a degree word that follows a form of "be", a feel/get/become/seem verb,
or "a": "is SO excited", "was PRETTY good", "is QUITE tired", "a BIT tangled", "a LITTLE".
Weaker negatives: other degree words (very, too, really, lot, super ...), Chinese degree
adverbs (很 太 真 超 挺 ...), the change verbs themselves (get, got, become, feel, started),
"to" after start/begin ("started TO"), "kind OF" / "sort OF", and "all" after a linking verb.
Mildly positive on code and regex sigils ($$, ${, \\$, @{, |^, .*, >&, \\r).
Everything else predicts 0. Magnitudes are rough least-squares fits on training text."""

READS = ()

COPULA = {"am", "is", "are", "was", "were", "be", "been", "being",
          "'m", "'re", "'s", "’s", "’re", "’m"}
FEEL_LINK = {"feel", "feels", "felt", "feeling", "get", "gets", "got", "getting", "become",
             "becomes", "became", "becoming", "looks", "look", "looked", "seem", "seems",
             "sound", "sounds", "grow", "grew", "growing"}
LINKING = COPULA | FEEL_LINK | {"a", "an"}
STRONG_DEGREE = {"so", "pretty", "quite", "bit", "little"}
WEAK_DEGREE = {"very", "too", "really", "extremely", "rather", "kinda", "totally", "slightly",
               "fairly", "highly", "incredibly", "absolutely", "lot", "super"}
DEGREE_ZH = {"很", "太", "真", "超", "挺", "有点", "有些", "比较", "这么", "那么", "特别", "格外",
             "非常", "超级", "巨"}
CHANGE = FEEL_LINK | {"started", "start", "starting", "starts", "began", "begin", "begins",
                      "beginning"}
START = {"start", "starting", "started", "starts", "begin", "began", "begins", "beginning"}
KIND = {"kind", "sort", "kinds", "sorts"}


SIGILS = {"\\$", " $$", " ${", "${", " @{", "|^", " |^", ".*", ">&", "\r", "#!", " %#", " ^"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    if raw in SIGILS:
        return None, 0.5
    word = raw.strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    linked = prev in LINKING
    if word in STRONG_DEGREE:
        return None, -2.2 if linked else -0.2
    if word in WEAK_DEGREE:
        return None, -0.6 if linked else -0.35
    if word in DEGREE_ZH:
        return None, -1.2
    if word == "to" and prev in START:
        return None, -2.7
    if word == "of" and prev in KIND:
        return None, -0.6
    if word == "all" and linked:
        return None, -1.0
    if word in CHANGE:
        return None, -0.4
    return None, 0.0

"""A '(' directly after a function or method name opens an argument list, which is
strongly negative in code. After a plain word it is weakly negative; after a single
maths letter or digit (f(x), P(A), 2(a+b)) it is mildly positive; after control keywords
(if, for, return) it is positive. Empty '()' is slightly negative."""
import re

READS = ()

CONTROL = {"if", "for", "while", "switch", "elif", "return", "sizeof"}
WORD = re.compile(r"\.?[A-Za-z_][A-Za-z_0-9]*")
ARG = re.compile(r"[A-Za-z_][A-Za-z_0-9]*")


def is_call_name(prev):
    """obj.method, camelCase, snake_case or Capitalised names: names of functions."""
    return prev.startswith(".") or bool(re.search(r"[a-z][A-Z]|_", prev)) or prev[:1].isupper()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if not s.startswith("("):
        return None, 0.0
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    rest = s[1:]
    if rest.startswith(")"):
        return None, -0.2
    if prev in CONTROL:
        return None, 0.7
    if re.fullmatch(r"[A-Za-z]|\d+", prev):
        return None, -1.0 if re.fullmatch(r"[A-Za-z_][A-Za-z_0-9]+", rest) else 0.4
    if WORD.fullmatch(prev):
        if is_call_name(prev):
            if rest == "":
                return None, -3.0
            if ARG.fullmatch(rest):
                return None, -2.2
            return None, -1.2 if prev.startswith('.') else -1.9
        return None, -0.8
    return None, 0.0

programs.sol:
"""Approximate a lexical opening-and-number detector.

At document openings, selected programming type/access spellings get positive
weights and most ordinary words get negative weights. Completing initial `12`
or `hydro` at the second token gives a strong positive pulse. Later rules cover
short numeral combinations, Chinese year prefixes, and a few code operators.
These are spelling tests, not parsing: `int` also matches the first token of
`intangibles`. Unmodeled token-specific variation is deliberately omitted.
"""

READS = ()

TYPES = {'int', 'char', 'float', 'uint'}
DECLARATIONS = {
    'package', 'using', 'def', 'import', 'from', 'var', 'module',
    'const', 'static', 'let',
}


def opening(s):
    w = s.strip()
    if s.startswith('<|') and s.endswith('|>'):
        return 0.30
    if s == 'void':
        return 3.18
    if s == 'bool':
        return 2.67
    if s in TYPES:
        return 1.95
    if s == 'string':
        return 1.61
    if s in {'double', 'byte', 'boolean'}:
        return 0.87
    if s in {'long', 'short'}:
        return 0.36
    if s == 'private':
        return 2.16
    if s == 'public':
        return 1.13
    if s == 'protected':
        return 0.33
    if s in DECLARATIONS:
        return 0.60
    if s.startswith(('/*', '"""', "'''", '##')):
        return 0.70
    if s in '0123456789' and len(s) == 1:
        n = int(s)
        if n == 0:
            return -0.55
        if n == 1:
            return 0.14
        return -0.04 - 0.025 * n
    if not w:
        return -0.025
    if w.isascii() and w.isalpha():
        if w.islower() and s[0].isspace():
            return -0.10
        if w.isupper():
            return -0.29
        return -0.19
    if w.isalpha():
        return -0.10
    return 0.01


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        pos, first, previous = 0, s, ''
    else:
        _, pos, first, previous = carry
        pos += 1

    value = -0.001
    if pos == 0:
        value = opening(s)
    elif pos == 1 and first == '1' and s == '2':
        value = 2.06
    elif pos == 1 and (first + s).lower() == 'hydro':
        value = 1.53
    elif s in {'0', '零', '〇', 'Ｏ'} and previous.endswith('二'):
        value = -0.90
    elif len(s) == 1 and s in '0123456789':
        n = int(s)
        value = -0.006
        if len(previous) == 1 and previous in '0123456789':
            tens = int(previous)
            if n == 1 and 1 <= tens <= 3:
                value = 0.11
            elif n == 0:
                if tens == 3:
                    value = 0.18
                elif tens:
                    value = -0.04
                else:
                    value = 0.0
    elif s == '九' and previous.endswith('一'):
        value = -0.60
    elif s == 'Ｏ' and previous.endswith('Ｏ'):
        value = -0.36
    elif s.strip() == 'const':
        value = 0.075
    elif s in {'::', '->'}:
        value = -0.065
    elif s.strip() == '=':
        value = -0.020
    elif s.startswith(';') and '\n' in s:
        value = -0.025

    return (doc, pos, first, s), value

programs.haiku:
"""Doc-start component: fires on the first token of a document (and on "1" "2" opening a document).
Elsewhere the component is near zero with no describable pattern."""
READS = ()

PREPS = {" of", " to", " a", " in", " by", " for", " on", " is", " was", " with", " or", " at", " an", " from", " as"}


def start_value(s):
    """Activation at the first token of a document, judged from that token alone."""
    if s.startswith("<|"):
        return 0.3  # chat/special markers
    if s.strip() == "":
        return 0.0
    if s[:1] == " " and s.strip() in PREPS:
        return -0.25  # prepositions and articles that continue a sentence
    t = s.strip()
    if t[:1].isdigit():
        return -0.17
    if t[:1] in "([{\"'`":
        return 0.12  # opening brackets and quotes, code-like starts
    if t[:1].isupper():
        return -0.21
    if t[:1].isalpha():
        return -0.07
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    k = 0 if carry is None or carry[0] != doc else carry[1] + 1
    s = prefix.token_strings[-1]
    v = 0.0
    if k == 0:
        v = start_value(s)
    elif k == 1 and prefix.token_strings[-2] == "1" and s == "2":
        v = 2.06  # a document opening with the digits "1" "2"
    return (doc, k), v

programs.sol:
"""Surface-syntax approximation of a code/metadata component.

The main signal is the return keyword: positive in brace-delimited code,
more negative after Python expressions or blank lines, and negative in
documentation fields.
There are also negative author/version metadata and repeated-nonbreaking-space
signals, with small fixed responses to await, print, and paired middle dots.
Only a short recent text buffer is kept, reset at document boundaries.
"""
import re

READS = ()
DOC_TAGS = {
    'return': -3.7,
    'author': -11.0,
    'since': -7.2,
    'version': -10.0,
    'package': -8.0,
    'subpackage': -7.2,
    'see': -1.2,
}


def return_signal(token, text, previous):
    # Treat escaped source and numbered/diff listings as ordinary code.
    source = re.sub(r'\\+n', '\n', text)
    source = re.sub(r'\\+t', '\t', source)
    source = re.sub(r'\n[ \t]*[+-]?[ \t]*(?:\d+[ \t]*)?$', '\n', source)
    last = source.rstrip()[-1:]
    inline = bool(source.split('\n')[-1].strip())
    if last in ('@', '\\'):
        return -3.7
    if token == 'return':
        if last == ':' and inline:
            return -4.8  # Sphinx :return: documentation field
        if last == '{':
            return 1.5 if inline else 0.8
        if last == ';' and inline:
            return 1.5
        return 0.6 if previous.endswith('\\t') else -0.4

    javascript = bool(re.search(
        r'\b(const|let|function|var|Promise|await|require|export)\b|=>',
        source))
    python = bool(re.search(
        r'\b(def|elif|self|except|None|True|False)\b'
        r'|\b(len|range|enumerate|isinstance|print|dict|list)\s*\('
        r'|\bfor\s+\w+\s+in\b|(?m:^[ \t]*#)', source))
    tab = token.startswith('\t')
    if last == '{':
        return (1.7 if tab else 1.9) + 0.5 * javascript
    if last == ';':
        return (0.3 if tab else 1.0) + 0.6 * javascript
    if last == ')':
        if inline:
            return 1.2
        return -1.9 if python else 1.2 if javascript else 0.4
    if last == ':':
        return -0.2 if python else 1.5 if javascript else 0.3
    if last == '}':
        return (-0.1 if tab else 0.4) + 0.6 * javascript
    return -1.2 if python and not inline else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, previous = '', ''
    else:
        _, text, previous = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if token == '\xa0':
        if not previous:
            value = -3.6
        elif previous.endswith('\xa0'):
            count = len(text) - len(text.rstrip('\xa0'))
            if count <= 2:
                value = -3.3 if count == 1 else -2.5
            else:
                value = -0.3
    elif previous in ('@', ' @') and token in DOC_TAGS:
        value = DOC_TAGS[token]
    elif token.startswith('@') and token[1:] in DOC_TAGS:
        value = 0.65 * DOC_TAGS[token[1:]]
    elif previous.endswith('__') and token in ('author', 'version'):
        value = -10.0 if token == 'author' else -2.7
    elif token == '··':
        value = 1.1
    elif token == ' await':
        value = 1.5
    elif token.strip() == 'print':
        value = -0.3
    elif token.strip() == 'return':
        value = return_signal(token, text, previous)
        if re.search(r'\n[ \t]*\n[ \t]*$', text):
            value -= 0.6
    return (doc, (text + token)[-600:], token), value

programs.haiku:
"""Layer-1 MLP down_proj component 4524: a `return`-statement detector.

It reads the token stream and predicts how strongly this component fires:
  * `return` as a code statement (`return x;`, `return self.x`):
    positive in brace-style code (C, Java, JavaScript, PHP, Go, ...), negative in
    Python-style code (`def`, `self`, `None`, ...). Style is a running score over the
    document: brace tokens (`;` `{` `}`) add 1, Python words subtract 1, decaying
    so that recent code counts most. A `return` straight after `{` is pushed up,
    one after `)` or `}` pushed down.
  * `return` as a Javadoc / docstring tag (`@return`) or in a comment line: negative,
    strongly for the tag.
  * the Javadoc tag `@author`: strongly negative.
  * a few statement keywords: `yield` and `print` a little negative; `break` and
    `await` a little positive.
  * everything else: 0.
"""

READS = ()

BRACE_MARKS = (";", "{", "}")
PY_WORDS = {"def", "self", "elif", "None", "import", "pass", "lambda", "True", "False", "print"}
DECAY = 0.98
RETURN_CODE_POS = 1.1
RETURN_CODE_NEG = -1.0
RETURN_TAG = -3.7
AUTHOR_TAG = -10.0
COMMENT_RETURN = -1.0
KW = {"yield": -0.5, "print": -0.25, "break": 0.46, "await": 1.2}


def _line_before(strings, t):
    """The text on the current line before token t (token t excluded)."""
    parts = []
    for i in range(t - 1, -1, -1):
        if "\n" in strings[i]:
            parts.append(strings[i].split("\n")[-1])
            break
        parts.append(strings[i])
    return "".join(reversed(parts)).strip()


def _prev_token(strings, t):
    """The last non-blank token before token t, stripped."""
    for i in range(t - 1, -1, -1):
        if strings[i].strip():
            return strings[i].strip()
    return ""


def step(carry, prefix, upstream):
    t = prefix.position
    strings = prefix.token_strings
    raw = strings[t]
    tok = raw.strip()
    prev = strings[t - 1] if t > 0 else ""

    new_doc = t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]
    brace, python = (0.0, 0.0) if (carry is None or new_doc) else carry
    brace *= DECAY
    python *= DECAY
    if any(m in raw for m in BRACE_MARKS):
        brace += 1.0
    if tok in PY_WORDS:
        python += 1.0
    score = brace - python

    value = 0.0
    if tok == "@author" or (tok == "author" and prev.endswith("@")):
        value = AUTHOR_TAG
    elif tok == "return":
        if prev.endswith("@"):
            value = RETURN_TAG
        elif _line_before(strings, t).startswith(("*", "//", "#", "/*")):
            value = COMMENT_RETURN
        else:
            value = RETURN_CODE_POS if score > 0 else RETURN_CODE_NEG
            before = _prev_token(strings, t)
            if before == "{":
                value += 0.8
            elif before in (")", "}"):
                value -= 0.8
    elif tok in KW:
        value = KW[tok]
    return (brace, python), float(value)

programs.sol:
"""A sparse detector of local date and time-expression continuations.

Negative values mark another detail after a time: a month after 年, a time
of day, a preposition, or a closing year parenthesis. Year ranges are mildly
positive, as are some annual/birth phrases and middle-dot separators.
Separate small rules cover 'National ...' names and dotted numbers.
Only a short text tail is retained, and it resets at document boundaries.
This approximates the pattern, not its full context-dependent strength.
"""
import re

READS = ()
UNITS = set('year years month months week weeks day days decade decades '
            'century centuries hour hours minute minutes second seconds'.split())
DAYS = set('monday tuesday wednesday thursday friday saturday sunday '
           'today yesterday tomorrow tonight'.split())
PARTS = set('morning afternoon evening night'.split())
PREPS = set('at for from in when as before after during on while between'.split())
YEAR = re.compile(r'(?<!\d)(?:1\d{3}|20\d{2})\Z')
MONTHS = ('January February March April May June July August September '
          'October November December Jan Feb Mar Apr Jun Jul Aug Sep Oct Nov Dec')
DATE = re.compile(r'\b(?:' + '|'.join(MONTHS.split()) + r')\.?'
                  r'(?:\s+\d{1,2}(?:st|nd|rd|th)?(?:,?\s+\d{4})?)?,?\Z', re.I)
TIME = re.compile(r'\b(?:years?|months?|weeks?|days?|hours?|minutes?|seconds?|'
                  r'time|morning|afternoon|evening|night)'
                  r'(?:\s+(?:ago|later))?,?\Z', re.I)
CJK_PART = re.compile(r'^(?:上午|下午|早上|晚上|午|夜|朝|白天|中午|傍晚|'
                      r'[春夏秋冬](?:天|季)?)')


def predict(text, previous, token):
    s = token.strip()
    if not s:
        return 0.0
    word, prev = s.lower(), previous.strip().lower()
    if token == '··':
        return 1.08 if previous == token else 0.075

    # A finer time specification after an East Asian calendar marker.
    tail = text.rstrip()
    if tail.endswith(('年', '년')):
        if s[0].isdigit() or s[0] in '一二三四五六七八九十零〇':
            return -3.5
        if s[0] in ')）' and '\n' not in token:
            return -2.5
        if s.startswith('生まれ'):
            return 2.2
    if tail.endswith(('月', '월')) and s[0].isdigit():
        return -0.25
    if tail.endswith(('年', '年的', '天', '日', '末')) and CJK_PART.match(s):
        return -4.3
    if tail.endswith(('日', '月')) and s[0] in ')）' and '\n' not in token:
        return -1.5
    if tail.endswith(('日', '今', '天')) and s[0] in '(（':
        return -2.7

    # A new field in a numerical date or dotted address/decimal.
    if s.isdecimal():
        if re.search(r'(?<!\d)(?:127|192|172)\.$', text):
            return -4.1 if s[0] in '01' else -1.2
        field = re.search(r'(?<!\d)(\d{2,4})[-/.]\Z', text)
        if field:
            n = field.group(1)
            if YEAR.fullmatch(n):
                return -2.4 if s[0] == '0' else -0.47
            if len(n) == 2:
                return -0.37 if s[0] == '0' else -0.06
            if len(n) == 3 and s[0] in '01':
                return -0.16

    if YEAR.search(text.rstrip(',')):
        if s in (')', '）', '),') and '\n' not in token:
            return -0.9 if s == '),' else -1.4
        if s == ');':
            return -0.3
        if word == 'when':
            return -1.4
        if word == 'at':
            return -1.8
        if word in {'as', 'for', 'from', 'before', 'by'}:
            return -0.35
        if word in {'and', 'the', 'to'} or s in {'–', '—'}:
            return 0.6 if re.search(r'\bbetween\s+\d{4}\Z', text, re.I) else 0.2
        if '·' in s:
            return 2.6

    # English named days, calendar dates, and duration words.
    if prev.rstrip('s') in DAYS:
        if word in PARTS or word == 'at':
            return -2.3
        if word in {'through', 'thru', 'to'}:
            return 1.0
        if word in PREPS:
            return -0.6
    if DATE.search(text) and word == 'at':
        return -1.8
    if prev in UNITS or prev == 'time':
        if word in PREPS:
            if prev == 'time':
                return -0.5 if word == 'when' else -0.05
            if prev in {'year', 'week', 'month', 'day'}:
                return -2.2 if word in {'at', 'for'} else -0.65
            return -0.25
    if (TIME.search(text) or prev.rstrip('s') in PARTS) and word in PREPS:
        return -0.75
    if word == 'when' and text.endswith(','):
        return -0.4
    if prev == 'national' and previous.strip().istitle() and s[0].isalpha():
        return -0.65
    if prev == 'annual' and word in {'report', 'reports', 'meeting', 'general'}:
        return 1.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text, previous = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    value = predict(text, previous, token)
    return (doc, (text + token)[-120:], token), value

programs.haiku:
"""Layer-1 MLP neuron 4525, read as a date and time detector.

The neuron is mostly quiet. It goes negative on the token that comes right after a date
or time expression, in the places where that token is most predictable:

- the month or day digit in "2019年1月", "2019-01", "2019/01" (strongest after 年);
- a closing bracket right after a time phrase, as in "(born 1984)";
- "at", "when", "for", "morning", "afternoon" right after a time word, as in
  "Sunday at", "every year for", "yesterday morning". The Chinese time-of-day words
  (晚上, 下午, 午, 凌晨, 冬天) are the strongest of these.

It goes mildly positive on a range connector after a year ("2010–2012", "2010 through"),
on a middle dot or bar after a date ("July 26, 2017 · Chess"), and on a run of middle
dots "··". Everything else predicts 0.

It reads only the few tokens just before the current one; it keeps no other state.
"""

import re

READS = ()

# Words that name a time, a date part, or a weekday.
TIME_WORDS = {
    "year", "years", "month", "week", "day", "night", "morning", "afternoon", "evening",
    "tonight", "today", "tomorrow", "yesterday", "monday", "tuesday", "wednesday",
    "thursday", "friday", "saturday", "sunday", "january", "february", "march", "april",
    "may", "june", "july", "august", "september", "october", "november", "december",
    "summer", "winter", "spring", "autumn", "ago", "noon",
    "年", "月", "日", "今年", "去年", "明年", "今天", "昨天", "明天", "每天", "周末", "本周末",
}
TIME_SUFFIXES = ("年", "月", "日", "天", "周", "週")  # a Chinese word ending in a time unit
DIGIT = re.compile(r"\d")
YEAR_MARKERS = {"年", "今年", "去年", "明年"}
CLOSERS = {")", "),", ").", "）", "）,", ");", "(", "（"}
CONNECTORS = {"–", "-", "through", "since", "to", "-to"}
DATE_MARKS = {"·", "|"}
PREPOSITIONS = {
