"""Approximate a negative response to short BE spellings and unfinished BE words.

Consonant-heavy fragments and BE split across tokens are strongest. Common
complete English words are attenuated. There are separate rules for be, bed
and best, and a fading count of German/Dutch/Scandinavian function words.
Cyrillic and katakana are transliterated; accents are removed. This captures
one dominant spelling pattern, not every lexical response of the component.
"""
import re
import unicodedata
from functools import lru_cache
import regex
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
MODALS = frozenset('to will would can could should shall may might must'.split())
ADVERBS = frozenset((
    'not cannot also only never still always then all even just ever '
    'soon probably really often already now again necessarily'
).split())
CONTRACTIONS = frozenset(("'t", '’t', "'ll", '’ll', "'d", '’d'))
DETERMINERS = frozenset('the a an my your his her its our their'.split())
FOREIGN_CUES = frozenset((
    'der die das des dem den und nicht auch sich für '
    'het een zijn niet voor deze dit og til ikke som det jeg du på med'
).split())

# Letters following BE: (BE... together, B | E..., BE | ...).
# These are spelling classes, not token identities.
RESPONSE = {
    'sch': (-4.249, -2.462, 0.0),
    'y': (-2.530, -2.209, -0.049),
    'm': (-1.847, -2.961, 0.0),
    'cgkq': (-3.114, -4.932, -2.193),
    'szſ': (-1.744, -2.462, -1.180),
    'bpw': (-4.168, -6.049, -2.203),
    'fvh': (-2.295, -6.005, -1.794),
    'dt': (-1.243, -2.432, -1.592),
    'lr': (-0.355, -0.645, -1.451),
    'n': (-0.052, -0.107, 0.0),
    'other': (-0.021, -0.522, -0.335),
}


@lru_cache(maxsize=32768)
def canonical(token):
    if regex.search(r'\p{Script=Cyrillic}|\p{Script=Katakana}', token):
        token = anyascii(token)
    return ''.join(c for c in unicodedata.normalize('NFD', token)
                   if not unicodedata.combining(c))


@lru_cache(maxsize=32768)
def spelling(token):
    word = canonical(token).lstrip(' \t\r\n_./-\'\"([{').lower()
    return word if word.isalpha() else ''


@lru_cache(maxsize=32768)
def attenuation(word):
    if word in ('be', 'bed', 'best'):
        return 1.0
    if len(word) >= 4 and zipf_frequency(word, 'en') >= 4.0:
        return 0.04
    return 0.05 if len(word) > 7 else 0.3 if len(word) > 5 else 1.0


def fragment_response(suffix, boundary):
    if suffix.startswith('sch'):
        return RESPONSE['sch'][boundary]
    for letters, values in RESPONSE.items():
        if letters not in ('sch', 'other') and suffix[:1] in letters and suffix:
            return values[boundary]
    return RESPONSE['other'][boundary]


def predict(raw, previous, language, word_prefix):
    token, previous = canonical(raw), canonical(previous)
    word, prev = spelling(raw), previous.strip().lower()
    internal = (bool(token) and token[0].isalpha()
                and bool(previous) and previous[-1].isalpha())
    if not (word.startswith('be') or
            internal and previous.lower().endswith(('b', 'be')) and word):
        return 0.0
    whole = word_prefix.lower() + word if internal else word
    english_ending = (internal and whole not in ('be', 'bed', 'best')
                      and len(whole) >= 4
                      and zipf_frequency(whole, 'en') >= 4.0)
    if word == 'be':
        if token.strip().islower() and prev in MODALS | ADVERBS | CONTRACTIONS:
            return -0.054
        base = -0.614 if token.strip().islower() and token.startswith(' ') else -0.838
        return base - 1.428 * language
    if raw.isascii() and word in ('bed', 'beds'):
        return (-2.860 if internal else -1.158) * (0.04 if english_ending else 1.0)
    if raw.isascii() and word == 'best':
        if prev in DETERMINERS:
            return -0.482
        return (-1.384 if token.startswith(' ') else -1.666) - 2.105 * language
    if word.startswith('be'):
        suffix, boundary, fragment = word[2:], 0, word
    elif internal and previous.lower().endswith('b') and word.startswith('e'):
        suffix, boundary, fragment = word[1:], 1, 'b' + word
    elif internal and previous.lower().endswith('be'):
        if word.startswith('ſ'):
            return -5.801
        suffix, boundary, fragment = word, 2, 'be' + word
    else:
        return 0.0
    factor = attenuation(fragment)
    if english_ending:
        factor = min(factor, 0.04)
    return factor * (fragment_response(suffix, boundary) - 0.301 * language)


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous, language, word = ('', 0.0, '')
    if carry is not None and carry[0] == doc:
        previous, language, word = carry[1:]
    value = -0.001 + predict(token, previous, min(1.0, language), word)
    cue = token.startswith(' ') and token.strip().lower() in FOREIGN_CUES
    language = min(3.0, language * 0.93 + float(cue))
    text = canonical(token)
    if text.isalpha():
        word = (word + text)[-40:]
    else:
        tail = re.search(r'[^\W\d_]+$', text)
        word = tail.group()[-40:] if tail else ''
    return (doc, token, language, word), float(value)

