HAN = regex.compile(r'\p{Script=Han}')
HIRAGANA = regex.compile(r'\p{Script=Hiragana}')
KATAKANA = regex.compile(r'\p{Script=Katakana}')

@lru_cache(None)
def label(word):
    if word in LABELS:
        return LABELS[word]
    if word.isascii() and word.isalpha():
        for lemma in wordnet.base_forms(word):
            name = LABELS.get(lemma)
            if name in INFLECTED:
                return name
    return None

# Negative, possessive, and reduced forms of are/am/have/will/had-or-would.
CONTRACTIONS = {
    "'t": -0.498, "n't": -0.498, "'s": -0.062,
    "'re": -0.672, "'m": -0.255, "'ve": -0.226,
    "'ll": -0.403, "'d": -0.547,
}

@lru_cache(None)
def properties(token):
    word = token.strip().lower().replace('’', "'")
    name = label(word)
    salient = float(name in SALIENT)
    value = SCORES.get(name, 0.0)

    value += CONTRACTIONS.get(word, 0.0)
    if word in {'got', 'gotten'}:
        value -= 0.380
    if word == 'doing':
        value -= 0.468
    if word == 'stuff':
        value -= 0.448
    if 'job' in wordnet.base_forms(word):
        value -= 0.673
    if len(word) > 1 and set(word) == {'·'}:
        value -= 1.397
    if token.strip().lower() != token.strip():
        value += salient * 0.065
    if not token.startswith(' '):
        value += salient * 0.175
    if HAN.search(word):
        value -= 0.040
    if HIRAGANA.search(word):
        value -= 0.034
    if KATAKANA.search(word):
        value -= 0.088
    return word, name, salient, value

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        carry = (doc, '', 0.0, 0.0)
    _, previous, previous_strength, older_strength = carry
    word, name, strength, lexical = properties(prefix.token_strings[-1])

    value = -0.003 + lexical
    value -= 0.082 * previous_strength + 0.025 * older_strength
    if first:
        value -= 0.013
    if previous in CONTEXT_AUX:
        value -= 0.108
    if strength and previous in FRAME:
        value -= 0.098
    if strength and previous_strength:
        value -= 0.076
    if word == 'to' and previous == 'going':
        value -= 1.001
    if word == 'of' and (label(previous) in {'vague_amount', 'vague_kind'}
                         or previous == 'out'):
        value -= 0.469
    if word in PARTICLES:
        verb = set(wordnet.base_forms(previous)) & {'be', 'turn', 'come', 'look'}
        if verb or previous == "'re" or label(previous) in {'get', 'go'}:
            value -= 0.182
    if word in {'on', 'in', 'out', 'up', 'off', 'down', 'over', 'into', 'back', 'around'}:
        if previous in CONTEXT_AUX - {"'ll"}:
            value -= 0.124
    if word == 'do' and previous == 'to':
        value -= 0.552
    return (doc, word, strength, previous_strength), float(value)

programs.haiku:
"""Layer-1 MLP down-projection component 4533: a casual-register feature.

What it does: the component pushes the residual stream negative on words of
casual, spoken or slang language (English, and some colloquial Chinese and
Japanese), and is near zero on most ordinary text. It is strongest on the word
that finishes a casual idiom, such as the "of" in "a bunch of" or the "to" in
"going to". It is weakly positive on formal and written words. The signal is
mostly lexical and diffuse: this list-based version explains about 6-7% of the
variance; the rest is spread over thousands of words and contexts.

The program predicts, for each token:
- "of" after a vague quantifier ("a bunch of", "a couple of", "a lot of"): -0.8
- "to" after "going" or "got" ("going to", "got to"): -1.2
- profanity and crude or slangy words ("shit", "damn", "dude", "gonna"): -0.8
- casual hedges ("basically", "really", "like", "kinda", "about"): -0.3
- contracted negations and auxiliaries ('t, 're, 'd, 'll): -0.2
- phrasal-verb particles ("put up", "clean out", "get off"): -0.3
- vague everyday nouns and quantifiers ("thing", "stuff", "job", "people"): -0.35
- casual adjectives and interjections ("good", "big", "okay", "cool"): -0.4
- casual verbs ("get", "got", "go", "do", "make", "take"): -0.2
- colloquial Japanese sentence endings ("って", "ない", "だ"): -0.4
- colloquial Chinese words ("挺", "妹子", "逼", "啪"): -0.5
- formal or academic English ("serious", "notably", "equality"): +0.2
- formal Chinese and Japanese ("教育", "希望", "ので", "という"): +0.2
- anything else: 0
"""

READS = ()

# Words that, after a vague quantifier or "going"/"got", make the next token strongly casual.
QUANT_PREV = {" bunch", " couple", " lot", " lots", " ton", " tons", " bit", " handful", " plenty", " load"}
GOING_PREV = {" going", " got", " gotta"}

SLANG = {" shit", " fuck", " fucking", " damn", " crap", " bullshit", " ass", " hell", " bitch",
         " sucks", " dick", " dude", " bro", " gonna", " wanna", " gotta", " kinda", " sorta"}
HEDGES = {" basically", " really", " like", " literally", " totally", " about", " bit", " anyone",
          " happening", " goes", " supposed", " etc"}
CONTRACTIONS = {"'t", "’t", "'re", "’re", "'d", "’d", "'ll", "’ll", "'ve", "’ve", "'m", "’m"}
PARTICLES = {" out", " up", " off", " down", " around", " away", " back"}
VAGUE = {" thing", " things", " stuff", " lot", " lots", " bunch", " kind", " sort", " deal",
         " way", " people", " kids", " kid", " guys", " guy", " folks", " girl", " boy", " man",
         " men", " job", " jobs", " gang", " mess", " nonsense", " dirt", " couple", " something",
         " nothing", " everything", " somebody", " everybody", " anything", " someone", " everyone"}
CASUAL_ADJ = {" good", " big", " bad", " cool", " okay", " pretty", " stupid", " crazy", " nice",
              " great", " awesome", " weird", " sweet", " silly", " cute", " funny", " yeah", " ok"}
CASUAL_VERB = {" get", " got", " gotten", " getting", " gets", " go", " going", " gone", " do",
               " doing", " done", " does", " did", " make", " put", " take", " come", " coming",
               " hang", " kick", " throw", " blow", " beat", " stick", " hit", " pop", " bump",
               " punch", " crack", " wipe", " toss", " roll", " figure"}
SLANG_JA = {"って", "ない", "だ", "な", "よ", "ね", "ちゃ", "じゃ", "そう"}
SLANG_ZH = {"挺", "妹子", "啪", "逼", "没", "毛", "死", "嫩", "奶", "吃", "老", "干", "很", "好",
            "个", "大", "给", "儿"}
FORMAL = {" serious", " truly", " deeply", " notably", " simply", " merely", " equality",
          " literature", " accordingly", " elsewhere", " shortly", " dear", " wealthy",
          " everywhere", " freely", " gently", " rarely", " peaceful", " ancient", " rural",
          " unfortunate", " Interestingly", " observation", " significantly"}
FORMAL_OTHER = {"など", "という", "もの", "ため", "ので", "教育", "健康", "希望", "社会", "发展",
                "讓", "让", "还", "受", "共", "遠", "进行", "国家"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if s == " of" and prev in QUANT_PREV:
        value = -0.8
    elif s == " to" and prev in GOING_PREV:
        value = -1.2
    elif s in SLANG:
        value = -0.8
    elif s in HEDGES:
        value = -0.3
    elif s in CONTRACTIONS:
        value = -0.2
    elif s in PARTICLES:
        value = -0.3
    elif s in VAGUE:
        value = -0.35
    elif s in CASUAL_ADJ:
        value = -0.4
    elif s in CASUAL_VERB:
        value = -0.2
    elif s in SLANG_JA:
        value = -0.4
    elif s in SLANG_ZH:
        value = -0.5
    elif s in FORMAL or s in FORMAL_OTHER:
        value = 0.2
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Mostly a detector of completed 'wire' spellings, including split words.

Wire/wired are strongly negative, wires/wiring somewhat less so.  Wireless
is not included.  There are weaker lexical responses to worry, wish and
willing, and to the Chinese characters for silk/thread and line/wire.
Split w-initial spellings have weaker letter-based responses.  Repeated
middle dots and the colon in a document-initial Title: header are separate
negative formatting responses.  Unrecognized tokens receive zero, omitting
the many weak background responses.
"""
import re
from opencc import OpenCC

READS = ()
SIMPLIFY = OpenCC('t2s')
WIRE = re.compile(r'(wire[sd]?|wiring|wiry)$', re.I)
WORRY = re.compile(r'^worr(y|ied|ies|ying)$')
WISH = re.compile(r'^wish(ed|es|ing)?$')


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    previous = carry[1] if same_doc else ''
    age = carry[2] + 1 if same_doc else 0
    joined = previous + text
    word = text.strip().lower()
    value = 0.0
    match = WIRE.search(joined)
    if match:
        ending = match.group().lower()
        split = not WIRE.search(text)
        if split:
            if ending == 'wire':
                value = -13.0
            elif ending == 'wiry':
                value = -8.0
            else:
                value = -11.5
        elif ending in ('wires', 'wiring'):
            value = -5.6
        else:
            value = -8.8
        if text.lower().endswith('wire') and word != 'wire':
            value = -10.5
        if text.startswith('_'):
            value *= 0.6
    elif age == 1 and previous.lower() == 'title' and text == ':':
        value = -7.265
    elif WORRY.fullmatch(word):
        value = -2.5 if word == 'worrying' else -3.5
    elif WISH.fullmatch(word):
        value = -1.2
    elif word == 'willing':
        value = -1.6
    elif word == 'wanted':
        value = -0.3
    elif word in ('wi', 'wir', 'wr', 'wre', 'wy'):
        value = -0.65
        if text.strip() == 'WI':
            value = -3.3
    elif previous.lower().endswith('w') and text and text[0].islower():
        if text.startswith(('ir', 'ij')):
            value = -3.5
        elif text.startswith('e'):
            value = 0.8
        elif text[0] in 'iruy':
            value = -0.9
    elif len(text) >= 2 and set(text) == {'·'}:
        value = -2.05
    elif len(text) == 1 and not text.isascii():
        simple = SIMPLIFY.convert(text)
        if simple == '丝':
            value = -3.2
        elif simple == '线':
            before = SIMPLIFY.convert(previous[-1:])
            value = -4.2 if before and before in '电铜导镍铝铁' else -0.6
    # Only the short spelling suffix is needed for split-token words.
    return (doc, joined[-16:], age), value

"""Local boundaries around short symbols and identifiers.

The main positive cases are assignment/comparison signs after short lowercase
names, powers, and closing inline-math/code delimiters. Punctuation immediately
after a document starts is stronger; the first token usually gets a negative
baseline. Repeated middle-dot separators have a separate positive response.
Most ordinary text gets a near-zero value.
Smaller bonuses cover other boundaries after short Latin names. Only the two
preceding tokens and document/line position are used.
"""
import re

READS = ()
EQUALITY = {'=', '==', '!=', ':=', '===', '!=='}
POWERS = {'^', '²', '³', '^{'}
COPULAS = {'is', 'are', 'was', 'were', 'be', 'been', 'being'}
FUNCTION_WORDS = {
    'is', 'in', 'on', 'to', 'or', 'an', 'as', 'be', 'at', 'by', 'we',
    'he', 'it', 'if', 'of', 'do', 'no', 'so', 'my', 'up', 'me', 'us',
}
ARITHMETIC = {
    '+', '-', '*', '/', '%', '**', '×', '∈', '≤', '≥', '<', '>', '<=', '>=',
}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos, line, previous, before = 0, 0, '', ''
    else:
        _, pos, line, previous, before = carry
    z, p, b = s.strip(), previous.strip(), before.strip()
    lower = p.islower()
    letters = any(c.isalpha() for c in z)
    digits = any(c.isdigit() for c in z)
    tail = re.search(r'[A-Za-z]+$', p)
    value = 0.002

    if len(z) >= 2 and set(z) == {'·'} and (pos == 0 or p == z):
        value = 1.19
    elif z in EQUALITY:
        if lower:
            if len(p) <= 3:
                if not b:
                    value = 1.43 if len(p) <= 1 else 0.90
                elif not s.startswith(' '):
                    value = 0.12
                else:
                    value = 0.57 if line <= 4 else 0.33
            else:
                value = 0.22 if line <= 3 else 0.046
        else:
            value = 0.35 if pos <= 6 else 0.023
    elif z in POWERS:
        value = (0.70 if pos <= 19 else
                 0.34 if not digits else 0.16) if tail else -0.01
    elif pos == 0:
        value = -0.44 if len(z) == 1 and z.isupper() else -0.065
    elif pos <= 2:
        if not letters and not digits:
            if pos == 1:
                value = (1.24 if len(p) <= 3 else 0.48) if lower else 0.34
            else:
                value = 0.60 if z[:1] in (')', ']', '}') else 0.185
        elif z in COPULAS or z in {'and', 'or', 'but'}:
            value = 0.23
    elif '$' in b and '$' in z:
        value = 1.01 if len(z) == 1 else 0.23
        if not before.startswith(' '):
            value = 0.027
    elif '$' in b and '\\' in z:
        value = 0.60 if s.startswith(' ') else 0.088
    elif '`' in z and lower:
        closes_code = len(b) <= 1 and z == '`' and not s.startswith(' ')
        value = 0.44 if closes_code else 0.06
    elif z == ')' and previous == ' \\' and len(b) <= 2 and b.isalpha():
        value = 1.2
    elif z in COPULAS and len(p) == 1 and p.isalpha():
        value = 0.55
    elif z in {'and', 'or'} and len(p) == 1 and p.isalpha():
        value = 0.32
    elif z == '::':
        value = 0.16
    elif pos <= 6 and not letters and not digits:
        value = 0.09

    # Short alphabetic names, including an attribute or argument such as .x or (t.
    name = p[1:] if p[:1] in ('.', '(') else p
    short_name = (name.isascii() and name.isalpha() and len(name) <= 2
                  and name.lower() not in FUNCTION_WORDS)
    if pos > 6 and short_name:
        if z in COPULAS:
            value = 0.36 if len(name) == 1 else 0.10
        elif z in {'and', 'or', 'but'}:
            value = 0.23 if len(name) == 1 else 0.07
        elif z in ARITHMETIC:
            value += 0.10
        elif z.startswith(','):
            value += 0.035
        elif z == ':':
            value += 0.13
        elif z[:1] in (')', ']', '}'):
            value += 0.065
        elif z[:1] in ('"', "'", '`', '$'):
            value += 0.06
        elif not z:
            value += 0.045
        elif z == '::':
            value += 0.19
        elif not any(c.isalnum() for c in z) and z not in EQUALITY:
            value += 0.035

    line = 0 if '\n' in s else line + 1
    return (doc, pos + 1, line, s, previous), value

programs.haiku:
"""layers.1.mlp.down_proj:4535 - fires on symbols that follow a short variable name.

In plain terms: this component is quiet almost everywhere. It switches on at a
punctuation or operator token that comes straight after a short name, such as the
"=" in "x = 3", the "^" or "$" in "x^2" or "$x$", or the ":" after "a". The
operators "=", "==", "!=" and the math symbols "$", "^", "`", "\\" are strongest
after a name of one to three letters, and weaker elsewhere. Punctuation after a
single letter gives a weak push. The second token of a document (the one right
after the first) gives a strong push when it is punctuation, and the first token
of a document gives a small negative push.

Values are the mean activations measured on training text, rounded.
"""

READS = ()

EQUALS = {"=", "==", "!="}
MATH_SYMBOLS = {"$", "$$", "^", "`", "\\"}
COLONS = {":", "::", '":"'}
SHORT_NAME_LETTERS = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")


def is_short_name(text):
    """One to three ASCII letters, optionally led by a space: 'x', ' ab', 'Ni'."""
    word = text.strip()
    return 1 <= len(word) <= 3 and all(ch in SHORT_NAME_LETTERS for ch in word)


def is_single_letter(text):
    word = text.strip()
    return len(word) == 1 and word in SHORT_NAME_LETTERS


def is_punctuation(text):
    return not any(ch.isalnum() for ch in text)


def step(carry, prefix, upstream):
    # carry: (document id of the previous token, how many tokens into its document)
    doc_id = prefix.document_ids[-1]
    if carry is None or carry[0] != doc_id:
        position = 0  # first token of a document
    else:
        position = carry[1] + 1
    new_carry = (doc_id, position)

    text = prefix.token_strings[-1]
    cur = text.strip()
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if position == 0:
        return new_carry, -0.08
    if position == 1 and is_punctuation(text):
        return new_carry, 0.65

    short = is_short_name(prev)
    if cur in EQUALS:
        return new_carry, 0.32 if short else 0.06
    if text in MATH_SYMBOLS or cur in MATH_SYMBOLS:
        return new_carry, 0.26 if short else 0.05
    if cur in COLONS and short:
        return new_carry, 0.12
    if is_punctuation(text) and is_single_letter(prev):
        return new_carry, 0.06
    return new_carry, 0.0

