"""Predict the positive response to o followed by a y/j-like glide.

Short Latin oy/oj and Cyrillic ой/оя pieces respond most; fused longer
words respond less. The pair can also cross a token boundary, without a
space. Case, token length, and Cyrillic iotated vowels set its strength.
A small secondary response covers repeated middle-dot formatting.
This approximation leaves most background and negative responses at zero.
"""
from anyascii import anyascii
import re

READS = ()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    s = raw.strip()
    if len(s) >= 2 and set(s) == {'·'}:
        return None, 0.8
    previous = ''
    if len(prefix.token_ids) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2]
    value = 0.0
    latin = bool(s) and all(ord(c) < 0x250 for c in s)
    if latin:
        word = anyascii(s).lower()
        match = re.search(r'o[yj]', word)
        if match:
            tail = word[match.end():]
            if not tail:
                if len(word) == 2:
                    value = 6.8 if not raw.startswith(' ') else 3.4
                elif len(word) == 3:
                    if raw.startswith(' '):
                        value = 4.9 if s[0].isupper() else 3.1
                    else:
                        value = 3.0 if s[0].isupper() else 5.3
                else:
                    value = 2.8 if len(word) == 4 and s[0].isupper() else 0.3
            elif tail == 's' and len(word) <= 4:
                value = 4.0 if not raw.startswith(' ') else 2.0
                if s[0].isupper():
                    value += 3.0
            else:
                value = 3.5 if tail == 'er' and len(word) == 4 else (
                    0.7 if len(word) <= 5 else 0.05)
            if 'o' not in s.lower():
                value *= 0.5
        if (not match and re.fullmatch(r'[a-z]?oi', word)
                and not word.startswith('j')
                and not previous.lower().endswith('j')):
            value = 1.4 if not raw.startswith(' ') else 0.2
    lower = s.lower()
    if re.search(r'о[яюйеё]', lower):
        if len(s) == 2:
            value = 5.6 if lower[1] in 'яю' else 1.3
            if lower[1] in 'её':
                value = 0.6
        elif 'оя' in lower:
            value = 2.7 if len(s) <= 4 else 0.35
        else:
            value = 0.1 if len(s) == 3 else 0.5
    if previous and raw and not raw[0].isspace():
        last = previous[-1]
        if ord(last) < 0x530:
            last = anyascii(last).lower()
        if last == 'o' or previous.lower().endswith('ou'):
            first = raw[0]
            if first in 'yY':
                value = max(value, (7.0 if len(s) == 1 else
                                    2.0 if s.isupper() else 7.0)
                            if len(s) <= 2 else
                            3.4 if len(s) == 3 else 0.6)
            elif first in 'jJ':
                value = max(value, 4.7 if len(s) == 1 else
                            3.3 if len(s) == 2 else
                            2.7 if len(s) == 3 else 0.3)
            elif first in 'яЯ':
                value = max(value, 8.0 if len(s) == 1 else
                            3.7 if len(s) == 2 else 0.6)
            elif first in 'юЮ':
                value = max(value, 1.8 if len(s) == 1 else 0.6)
            elif first in 'ёЁйЙ':
                value = max(value, 3.5 if len(s) == 1 else 0.6)
            elif first in 'еЕ':
                value = max(value, 2.4 if len(s) <= 2 else 0.6)
            elif first in 'иИїЇ':
                value = max(value, 2.0 if len(s) == 1 else
                            1.2 if len(s) == 2 else 0.5)
            elif first in 'iI':
                value = max(value, 1.4 if len(s) == 1 else
                            1.7 if s[1] in 'ae' else 0.0)
            elif first in 'eE':
                value = max(value, 0.2)
    return None, max(0.0, value)

"""Approximate several recurring lexical and syntactic patterns.

File extensions usually give negative values; programming-language names and
closing markup attribute values give positive ones. English conditionals differ
from the 'if' introducing an indirect yes/no question. Smaller rules cover
determiners, URL/JSON endings, date ordinals, and two interface labels.
Chinese light verbs get larger values after purpose/manner cues, rather than
in literal-direction or Japanese uses. Traditional forms are normalized by
OpenCC. The document-local tail is limited to 512 characters. This is a
sparse approximation: most ordinary tokens get a value near zero.
