import regex as re
from opencc import OpenCC

READS = ()
SIMPLIFY = OpenCC('t2s')
DAY_ORDINAL = re.compile(
    r'\b(?:[1-9]|[12]\d|3[01])(?:st|nd|rd|th)$'
)
CHINESE_CUE = re.compile(
    r'根据|按照|通过|利用|采用|以|为了|需要|能够|'
    r'可以|应该|应当|必须|'
    r'要|用|将|对|把|让|使|为'
)
