    r'.{1,40}$'
)

# Filename suffixes, with strengths estimated on training text.
FILE_SUFFIX = {
    'rs': -0.41, 'mod': -0.58,
    'json': -0.37, 'yaml': -0.36, 'yml': -0.35,
    'sh': -0.34, 'jar': -0.37, 'zip': -0.50,
    'cfg': -0.47, 'conf': -0.49,
    'txt': -0.29, 'md': -0.20, 'spec': -0.28,
    'go': -0.17, 'py': -0.11,
    'js': -0.08, 'ts': -0.03, 'html': -0.08,
    'php': -0.05, 'xml': -0.27, 'cpp': -0.36,
    'vue': -0.28, 'pdf': -0.30,
}
LANGUAGES = {'python', 'java', 'javascript', 'typescript',
             'ruby', 'rust', 'php'}
QUESTION_IF = {'check', 'see', 'know', 'wonder', 'sure', 'ask',
               'determine', 'test', 'doubtful', 'uncertain'}
CONDITIONAL_IF = {'even', 'only', 'what', 'but', 'now', 'especially'}
DEMONSTRATIVE_PREPS = {'in', 'at', 'of', 'to', 'for', 'from', 'after',
                       'before', 'by', 'with', 'on', 'about', 'like'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    # Normalize escaped quotes/newlines in code embedded in JSON strings.
    text = re.sub(r'\\+"', '"', token).replace('\\n', '\n')
    value = -0.001
    word = token.strip()
    lower = word.lower()
    prev_word = ''
    if lower in {'if', 'that'}:
        previous = re.search(r'([A-Za-z]+)\W*$', tail)
        prev_word = previous[1].lower() if previous else ''

    if token.startswith('.') and token[1:] in FILE_SUFFIX:
        value = FILE_SUFFIX[token[1:]]
    elif (token == word and word in FILE_SUFFIX
          and tail.endswith('.')):
        # A tokenizer may split the dot off the extension.
        value = -0.25 if word in {'js', 'ts'} else -0.55
    elif lower in LANGUAGES:
        value = 0.11 if lower != 'typescript' else 0.18
    elif token[:1] in {'/', '-'} and lower[1:] in LANGUAGES | {'go'}:
        value = 0.23
    elif (token in {'#', 'Sharp', 'sharp'}
          and tail.endswith(('C', 'c'))):
        value = 0.60 if token == 'Sharp' else 0.45
    elif lower == 'html' and tail.rstrip().endswith('```'):
        value = -0.23
    elif lower == 'if':
        value = 0.08 if word == 'If' else 0.025
        if token == 'if':
            value = -0.06
        if prev_word in QUESTION_IF:
            value = -0.07
        elif prev_word in CONDITIONAL_IF or tail.rstrip().endswith(','):
            value = 0.14
    elif lower == 'that':
        value = 0.10 if word == 'That' else 0.0
        if prev_word in DEMONSTRATIVE_PREPS:
            value = 0.19
        elif prev_word == 'so':
            value = -0.025
    elif lower == 'those':
        value = 0.07
    elif lower == 'this':
        value = -0.005 if word == 'This' else -0.02
    elif lower == 'each':
        value = 0.058
    elif lower == 'other':
        value = -0.05
    elif token == '://':
        value = 0.074
    elif token == '"}}\n':
        value = 0.15

    # Date wording and a few common web-interface labels.
    if lower == 'of' and DAY_ORDINAL.search(tail):
        value = -0.39
    elif lower == 'level' and tail.rstrip().endswith('Challenge'):
        value = -0.075
    elif lower == 'more' and tail.rstrip().endswith('View'):
        value = -0.28

    if not word.isascii():
        han_word = SIMPLIFY.convert(word)
        if han_word in {'来', '去', '予以', '进行', '来进行'}:
            clause = re.split(r'[，。！？；\n]', tail)[-1][-40:]
            japanese = re.search(r'\p{Hiragana}|\p{Katakana}', clause)
            clause = SIMPLIFY.convert(clause)
            cue = bool(CHINESE_CUE.search(clause))
            if japanese:
                value = -0.08
            elif han_word == '予以':
                value = 0.43
            elif han_word == '来进行':
                value = 0.34
            elif han_word == '进行':
                value = 0.17 if cue else 0.07
            elif MANNER_PHRASE.search(clause):
                value = 0.36
            elif cue:
                value = 0.20 if han_word == '来' else 0.09
            else:
                value = -0.06

    if '"' in text or '}' in text:
        # Only bare closing quotes (not a quote fused with '>' or ',').
        tag = re.search(r'<[A-Za-z][^<>]*$', tail)
        if tag and re.fullmatch(r'[^"<>]*"', text):
            if re.search(r'=\s*"[^"<>]*$', tag[0]):
                value = 0.50
        elif tag and text == '="#"':
            value = 0.85
        elif tag and re.fullmatch(r'[^{}<>]*}+\s*', text):
            # JSX braces delimit an attribute expression, like HTML quotes.
            expression = re.search(r'=\s*(\{[^<>]*)$', tag[0])
            if expression:
                body = expression[1]
                depth = body.count('{') - body.count('}')
                if depth > 0 and depth + text.count('{') == text.count('}'):
                    value = 0.60

    return (doc, (tail + text)[-512:]), value

"""Approximate a short 'a'-ending detector.

Predict negative activations for a/A and for pieces ending in a, especially
inside capitalized words. Transliteration extends this rule across scripts;
longer pieces weaken it. Small side rules cover articles, 'there', and a few
text-formatting markers. Individual words' idiosyncratic strengths are omitted.
"""
import re
import unicodedata
from anyascii import anyascii
from functools import lru_cache

READS = ()

# Typical strength for a one-character piece with an a-final transliteration.
SCRIPT_STRENGTH = {
    'ARABIC': -0.365, 'CJK': -0.343, 'CYRILLIC': -0.715,
    'GREEK': -0.665, 'HANGUL': -0.731, 'HIRAGANA': -0.417,
    'KATAKANA': -1.535, 'LATIN': -0.621,
}


def decode_piece(pending, raw):
    """Delay incomplete UTF-8 characters until their remaining bytes arrive."""
    data = pending + raw
    try:
        return data.decode('utf8'), b''
    except UnicodeDecodeError as error:
        if error.reason == 'unexpected end of data':
            return (data[:error.start].decode('utf8', 'replace'),
                    data[error.start:])
        return data.decode('utf8', 'replace'), b''


@lru_cache(maxsize=65536)
def local_response(s):
    t = s.strip()
    low = t.lower()
    value = -0.004
    a_piece = False
    if low.endswith('a') and t.isascii():
        letters = ''.join(c for c in t if c.isalpha())
        if low == 'a':
            value -= 0.998
            if not s[:1].isspace():
                value -= 0.080
            a_piece = True
        elif letters.lower() == 'a':
            value -= 0.810  # a letter attached to punctuation, e.g. '(a'
        else:
            a_piece = True
            value += -0.705 + 0.066 * max(0, min(len(t), 10) - 3)
            if s[:1].isspace():
                value += 0.104
                if low in {'la', 'una'}:  # Romance feminine articles
                    value += 0.667
            if t.isupper():
                value -= 0.293
            elif t[:1].isupper():
                value -= 0.295
    elif low and not t.isascii() and anyascii(low).endswith('a'):
        name = unicodedata.name(t[-1], '')
        script = next((s for s in SCRIPT_STRENGTH if s in name), None)
        strength = SCRIPT_STRENGTH.get(script, -0.942)
        value += min(0.0, strength + 0.133 * min(len(t) - 1, 6))

    if low == 'an':
        value -= 0.182
    elif low == 'there':
        value -= 0.601
    elif low == 'as':
        value -= 0.039
        if not s[:1].isspace():
            value -= 0.594
    if not t and '\t' in s and s.endswith(' '):
        value += -0.893 + (0.594 if len(s) < 4 else 0.0)
    if t and set(t) == {'#'} and len(t) > 1:
        value -= 0.489 * min(len(t) - 1, 2)
    if '\x00' in s:
        value -= 1.305
    if t and set(t) == {'·'} and len(t) > 1:
        value += 0.963
    return value, a_piece


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, pending = (carry[1:] if carry is not None and carry[0] == doc
                         else ('', b''))
    s, pending = decode_piece(pending, prefix.token_bytes[-1])
    value, a_piece = local_response(s)
    if a_piece and previous and s[:1].isalpha():
        value += -0.428 + 0.091 * min(len(previous), 10)
        if previous[:1].isupper():
            value -= 0.729
    tail = re.search(r'[^\W\d_]+$', (previous + s)[-64:], re.UNICODE)
    word = tail.group() if tail else ''
    return (doc, word, pending), float(value)

