"""Layer-1 MLP down-projection, component 4543.

What it does: it goes negative on tokens that are, or are built around, the open
vowel "a" -- the English article "a"/"A", and short syllables with an /a/ sound
written in any script: Latin fragments ending in a ("ra", "ta", "ya", "stra"),
Katakana a-row kana (ア カ サ タ ナ ハ マ ヤ ラ ワ ...), Korean syllables with the
vowel ㅏ/ㅑ (가 사 자 라 ...), and Cyrillic words ending in а or я (а, на, за).
Indentation tokens made of a tab plus spaces also push it negative (about -1).
Everything else is predicted as 0 (the component's typical value).

The magnitudes are rough per-class averages measured on training text.
"""

READS = ()

KATAKANA_A_ROW = set("アカサタナハマヤラワガザダバパャ")


def is_latin_a_syllable(token):
    # short, letters only, ends in the letter a: "ra", "stra", "CA", "ya", "data"
    return token.isalpha() and token.isascii() and len(token) <= 5 and token.lower().endswith("a")


def is_korean_a_syllable(char):
    # Hangul syllables are 0xAC00 + (lead*21 + vowel)*28 + tail; vowels 0 (ㅏ) and 2 (ㅑ) are "a"
    code = ord(char)
    return 0xAC00 <= code <= 0xD7A3 and ((code - 0xAC00) // 28) % 21 in (0, 2)


def activation_for(token):
    text = token.strip()
    if token.startswith("\t") and text == "":
        return -1.0  # tab indentation
    if not text:
        return 0.0
    if text in ("a", "A"):
        return -1.0  # the article a, or the letter a
    if is_latin_a_syllable(text):
        return -1.0 if not token.startswith(" ") else -0.6
    if all(c in KATAKANA_A_ROW for c in text):
        return -1.6
    if all(is_korean_a_syllable(c) for c in text):
        return -0.9
    if all("Ѐ" <= c <= "ӿ" for c in text) and text[-1] in "аяАЯ":
        return -0.8
    return 0.0


def step(carry, prefix, upstream):
    return carry, activation_for(prefix.token_strings[-1])
